window.QUESTIONS = [
{"id":1,"question":"Câu 1 (Nhận biết): Ở giai đoạn giáo dục cơ bản, môn Tin học là môn bắt buộc, được dạy liên tục trong khoảng thời gian nào dưới đây?","options":["A. Lớp 6 đến lớp 9.","B. Lớp 3 đến lớp 12.","C. Lớp 3 đến lớp 9.","D. Lớp 1 đến lớp 9."],"correctIndex":2,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":2,"question":"Câu 2 (Nhận biết): Hãy cho biết ngoài việc hình thành và phát triển năng lực tin học, loại tri thức nào dưới đây được chương trình môn Tin học ở cấp THPT cung cấp cho học sinh?","options":["A. Tri thức chuyên sâu về lập trình nâng cao nhằm chuẩn bị cho các kỳ thi học sinh giỏi quốc gia.","B. Tri thức mang tính định hướng nghề nghiệp thuộc lĩnh vực tin học/ứng dụng tin học.","C. Tri thức toàn diện về mọi ngành nghề trong xã hội hiện đại, không giới hạn ở lĩnh vực tin học.","D. Tri thức nền tảng về khoa học máy tính, tương tự mục tiêu đã đạt được ở cấp THCS."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":3,"question":"Câu 3 (Nhận biết): Theo Chương trình Giáo dục phổ thông 2018, vị trí của môn Tin học ở cấp trung học phổ thông được xác định như thế nào trong hệ thống các môn học?","options":["A. Là môn học bắt buộc đối với tất cả học sinh nhằm hoàn thiện năng lực tin học cơ bản.","B. Là môn học lựa chọn, có vị trí bình đẳng như các môn học khác (Vật lí, Hóa học...).","C. Là môn học bổ trợ, tập trung chủ yếu vào việc hướng dẫn học sinh thao tác trên phần mềm.","D. Là môn học tích hợp, được ghép cơ học với phân môn Công nghệ trong suốt cấp học."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":4,"question":"Câu 4 (Thông hiểu): Yếu tố nào dưới đây thể hiện bản chất đặc thù khiến môn Tin học không thể bị thay thế bởi các môn học khác trong Chương trình GDPT 2018?","options":["A. Tập trung rèn luyện kĩ năng thao tác kĩ thuật trên các thiết bị số và sử dụng thành thạo các phần mềm ứng dụng phổ thông.","B. Có đối tượng xử lý là thông tin, dữ liệu vô hình trong môi trường số nhằm mục tiêu nối dài trí tuệ và phát triển tư duy máy tính.","C. Giữ vai trò độc quyền trong việc hình thành, phát triển 5 phẩm chất chủ yếu và 3 năng lực chung cho học sinh phổ thông.","D. Đảm nhận việc hợp nhất toàn bộ nội dung giáo dục thuộc các lĩnh vực Kĩ thuật, Công nghệ và Nghệ thuật thành một môn học."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":5,"question":"Câu 5 (Thông hiểu): Đặc điểm nào sau đây thể hiện rõ nhất sự phát triển về tư duy giải quyết vấn đề của học sinh từ cấp Tiểu học lên cấp Trung học cơ sở (THCS)?","options":["A. Sự chuyển biến từ tìm hiểu sâu về tổ chức dữ liệu đến định hướng nghề nghiệp trong lĩnh vực tin học.","B. Sự nâng cao từ rèn luyện thao tác cơ bản trên máy tính đến kĩ năng lập trình các phần mềm ứng dụng.","C. Sự phát triển từ ý tưởng điều khiển máy tính đến khả năng chia nhỏ vấn đề và sử dụng khái niệm thuật toán.","D. Sự mở rộng từ nội dung Học vấn số hoá phổ thông (DL) đến trọng tâm là mạch kiến thức Khoa học máy tính."],"correctIndex":2,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":6,"question":"Câu 6 (Thông hiểu): Một trong những cách hiểu sai lầm về môn Tin học là \"đồng nhất môn Tin học với một môn công nghệ thuần túy\". Cơ sở nào dưới đây giải thích cho sự sai lầm này dựa trên đặc thù xử lí của môn học?","options":["A. Được định hướng lồng ghép chung với phân môn Công nghệ thành một thể thống nhất ở cấp tiểu học.","B. Tập trung rèn luyện các thao tác sử dụng phần mềm ứng dụng để phục vụ trực tiếp cho đời sống.","C. Lấy thông tin và dữ liệu vô hình làm đối tượng xử lí thay vì các thực thể vật lí hữu hình.","D. Cung cấp những kiến thức nền tảng về hệ thống máy tính và các ứng dụng kĩ thuật số thực tiễn."],"correctIndex":2,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":7,"question":"Câu 7 (Thông hiểu): Trong Chương trình GDPT 2018, môn Tin học được xác định giữ vai trò trung tâm kết nối và hỗ trợ đắc lực cho giáo dục STEM/STEAM. Sự đóng góp cốt lõi này xuất phát từ lý do nào sau đây?","options":["A. Môn Tin học đóng vai trò chủ đạo nhờ cung cấp hệ thống phần mềm máy tính và công cụ đa phương tiện phục vụ cho việc mô phỏng, trình bày, báo cáo kết quả dự án STEM.","B. Môn Tin học hình thành cho học sinh Tư duy máy tính và là công nghệ nền tảng hội tụ đủ cả bốn yếu tố S, T, E, M giúp kết nối hiệu quả các lĩnh vực STEM.","C. Môn Tin học tích hợp toàn bộ nội dung giáo dục cốt lõi của môn Toán, Vật lí, Hóa học và Công nghệ vào mạch Khoa học máy tính để triển khai dạy học liên môn toàn diện.","D. Môn Tin học trang bị nội dung bắt buộc về lắp ráp, lập trình điều khiển robot giáo dục ở tất cả các cấp học để giúp học sinh tạo ra sản phẩm tự động hóa thực tế."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":8,"question":"Câu 8 (Vận dụng): Ban tư vấn hướng nghiệp của một trường THPT đang xếp lịch tư vấn chọn môn học cho học sinh lớp 10. Học sinh A có nguyện vọng sau này theo học ngành Thiết kế Đồ họa và Truyền thông Đa phương tiện, trong khi học sinh B có nguyện vọng theo học ngành Kỹ thuật Phần mềm và Trí tuệ Nhân tạo (AI). Dựa trên quan điểm xây dựng và mục tiêu phân hóa của Chương trình môn Tin học ở cấp THPT,  đâu là định hướng phù hợp nhất dành cho học sinh?","options":["A. Tư vấn cho học sinh A chọn định hướng Tin học ứng dụng (ICT); tư vấn cho học sinh B chọn định hướng Khoa học máy tính (CS).","B. Tư vấn cho cả hai học sinh chọn định hướng Khoa học máy tính (CS) vì đây là mạch kiến thức duy nhất giúp phát triển tư duy sáng tạo và ứng dụng nghệ thuật số.","C. Tư vấn cho học sinh B chọn định hướng Tin học ứng dụng (ICT); tư vấn cho học sinh A chuyển sang chọn môn Nghệ thuật thay vì môn Tin học.","D. Tư vấn cho cả hai học sinh chọn chung định hướng Tin học ứng dụng (ICT) nâng cao, vì công nghệ số hiện đại đã xóa bỏ hoàn toàn ranh giới giữa ICT và CS."],"correctIndex":0,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":9,"question":"Câu 9 (Vận dụng): Trong đợt tập huấn nâng cao năng lực dạy học môn Tin học cấp THCS, hai giáo viên tranh luận về việc thiết kế mục tiêu sản phẩm đầu ra cho dự án học tập của học sinh lớp 9; căn cứ vào mục tiêu cụ thể của chương trình môn Tin học 2018 ở cấp THCS, giáo viên nên định hướng xây dựng mục tiêu như nào sau đây để vừa đảm bảo đúng chuẩn vừa tránh gây quá tải?","options":["A. Chỉ cần yêu cầu học sinh biết phân rã bài toán, mô hình hóa thuật toán qua lập trình trực quan và tạo ra sản phẩm số đơn giản phục vụ học tập, tránh đưa ra chỉ tiêu vượt quá cấp học.","B. Phải bắt buộc học sinh tối ưu hóa độ phức tạp thuật toán nâng cao và thương mại hóa sản phẩm số, nhằm đáp ứng yêu cầu chuyển giao công nghệ ở giai đoạn giáo dục định hướng nghề nghiệp tương lai.","C. Nên hạn chế ở mức độ làm quen thiết bị số và giải trí đơn giản như cấp tiểu học, vì học sinh THCS chưa đủ năng lực tư duy để thực hiện thao tác kiểm thử và sửa lỗi sản phẩm.","D. Cần tập trung hoàn toàn vào việc giảng dạy cú pháp ngôn ngữ lập trình mã lệnh phức tạp, bỏ qua khâu thiết kế giao diện cùng khả năng chia sẻ các sản phẩm số trong môi trường học tập cộng đồng."],"correctIndex":0,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":10,"question":"Câu 10 (Vận dụng): Tình huống: Năm học mới, Ban Giám hiệu một trường Tiểu học chuẩn bị phân công giáo viên giảng dạy môn Tin học và Công nghệ lớp 3. Trong họp hội đồng chuyên môn, một ý kiến đề xuất: \"Vì đây là môn học tích hợp ở cấp tiểu học nhằm giảm tải số lượng môn học, nhà trường nên giao cho giáo viên môn Công nghệ dạy luôn phân môn Tin học sau khi bồi dưỡng ngắn hạn để tiết kiệm đầu mối giáo viên.\" Căn cứ vào đặc điểm vị trí và bản chất môn học ở cấp Tiểu học trong Chương trình GDPT 2018, nhận định nào dưới đây phản ánh chính xác nhất về đề xuất trên?","options":["A. Đúng, vì môn Tin học và Công nghệ ở cấp tiểu học được thiết kế theo hướng tích hợp liên môn, giúp giảm bớt số lượng môn học cho học sinh tiểu học.","B. Sai, vì môn Tin học và Công nghệ ở tiểu học là môn ghép cơ học hai phân môn độc lập có mục tiêu riêng; hiểu sai dẫn tới quyết sách nguy hại.","C. Sai, vì phân môn Tin học ở cấp tiểu học là môn học tự chọn nên nhà trường không được phép tự ý ghép chung với môn Công nghệ mang tính bắt buộc.","D. Đúng, vì nội dung Tin học cấp tiểu học mang tính chất công nghệ thuần túy, chưa chứa đựng hàm lượng khoa học máy tính nên giáo viên Công nghệ đảm nhiệm được."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":11,"question":"Câu 1 (Nhận biết): Phương án nào sau đây nêu đúng hai định hướng phân hóa của chương trình môn Tin học ở cấp Trung học phổ thông?","options":["A. Tin học ứng dụng (ICT) và Khoa học máy tính (CS).","B. Học vấn số hóa (DL) và Tin học ứng dụng (ICT).","C. Thiết kế hệ thống mạng và Lập trình ứng dụng.","D. Khai phá dữ liệu và Trí tuệ nhân tạo."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":12,"question":"Câu 2 (Nhận biết): Phương án nào sau đây nêu đúng số lượng chủ đề chính xuyên suốt từ cấp Tiểu học đến Trung học phổ thông trong hệ thống nội dung giáo dục cốt lõi của môn Tin học?","options":["A. 5.","B. 7.","C. 6.","D. 8."],"correctIndex":1,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":13,"question":"Câu 3 (Nhận biết): Dựa trên định hướng phân hóa ở giai đoạn giáo dục định hướng nghề nghiệp, chương trình đưa ra quy định như thế nào đối với học sinh cấp trung học phổ thông về những lựa chọn học tập môn Tin học?","options":["A. Được yêu cầu học chung một nội dung thống nhất nhằm củng cố vững chắc nền tảng kĩ năng sử dụng máy tính.","B. Sẽ quyết định lựa chọn theo một trong hai định hướng học tập là Tin học ứng dụng hoặc Khoa học máy tính.","C. Bắt buộc phải tham gia đầy đủ tất cả các cụm chuyên đề học tập để đảm bảo sự phát triển năng lực toàn diện.","D. Tự do lựa chọn bất kì mạch kiến thức nào trong ba mạch cấu thành môn học tùy theo sở thích cá nhân."],"correctIndex":1,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":14,"question":"Câu 4 (Thông hiểu): Xét theo định hướng phát triển năng lực, đặc điểm nào dưới đây thể hiện sự khác biệt cốt lõi về mục tiêu giữa mạch Khoa học máy tính (CS) với hai mạch ICT và DL?","options":["A. CS tập trung nghiên cứu nguyên lý nhằm sáng tạo công cụ mới, trong khi ICT và DL chú trọng khai thác công cụ có sẵn để giải quyết vấn đề.","B. CS chỉ rèn luyện kĩ năng lắp ráp phần cứng máy tính, trong khi ICT và DL tập trung hoàn toàn vào việc thao tác phần mềm văn phòng.","C. CS được thiết kế dành riêng cho học sinh chuyên Tin cấp THPT, trong khi ICT và DL áp dụng cho tất cả các đối tượng học sinh còn lại.","D. CS yêu cầu tổ chức giảng dạy thuần lý thuyết không cần máy tính, trong khi ICT và DL bắt buộc dành 100% thời lượng cho thực hành."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":15,"question":"Câu 5 (Thông hiểu): Đặc điểm nào sau đây thể hiện sự thay đổi trong việc phát triển tư duy thuật toán và lập trình cho học sinh tiểu học và trung học cơ sở ở Chương trình môn Tin học 2018 so với chương trình 2006?","options":["A. Tập trung hướng dẫn sử dụng các phần mềm mô phỏng nhằm hỗ trợ giải quyết bài tập của các môn học khác.","B. Chú trọng rèn luyện tư duy logic thông qua việc mô tả các bước giải bài toán bằng ngôn ngữ tự nhiên.","C. Khai thác ngôn ngữ lập trình trực quan nhằm tạo điều kiện cho học sinh sớm tự làm ra các sản phẩm số.","D. Yêu cầu học sinh phân tích cấu trúc của thiết bị thông minh để hiểu quy trình hoạt động của máy tính."],"correctIndex":2,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":16,"question":"Câu 6 (Thông hiểu): Trong Chương trình môn Tin học, biểu hiện nào sau đây của mạch Khoa học máy tính (CS) thể hiện rõ nhất tư duy máy tính trong giải quyết vấn đề?","options":["A. Lựa chọn, đánh giá và tích hợp linh hoạt các giải pháp công nghệ hiện hành nhằm tự động hóa quy trình xử lí dữ liệu trong các dự án học tập liên môn.","B. Vận dụng phương pháp trừu tượng hóa để phân rã nhiệm vụ phức tạp, đồng thời trích chọn các đặc trưng cốt lõi nhằm mô hình hóa và xây dựng thuật toán giải quyết.","C. Khai thác chuyên sâu hệ thống cú pháp và thư viện của ngôn ngữ lập trình bậc cao để kiến tạo nên các phần mềm ứng dụng đáp ứng nhu cầu thực tiễn xã hội.","D. Phối hợp đồng bộ nền tảng phần cứng và thiết bị ngoại vi thông minh nhằm thiết kế hệ thống tự động hóa bám sát các tiêu chuẩn cốt lõi của phương pháp giáo dục STEM."],"correctIndex":1,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":17,"question":"Câu 7 (Thông hiểu): Nguyên tắc nào dưới đây phản ánh đúng bản chất mối quan hệ giữa Yêu cầu cần đạt, Nội dung giáo dục và các thành phần năng lực Tin học trong Chương trình GDPT môn Tin học?","options":["A. YCCĐ và Nội dung giáo dục có mối quan hệ tương hỗ, biện chứng; các thành phần năng lực mang tính tích hợp, bổ trợ lẫn nhau nên một hoạt động dạy học có thể phát triển đồng thời nhiều thành phần năng lực.","B. YCCĐ quyết định tuyệt đối Nội dung giáo dục; mỗi mạch kiến thức được quy định gắn liền ứng với một thành phần năng lực riêng biệt nhằm đảm bảo việc kiểm tra đánh giá chuẩn đầu ra không bị chồng chéo lẫn nhau.","C. Nội dung giáo dục giữ vai trò nền tảng quyết định YCCĐ; việc đánh giá học sinh bắt buộc phải tách biệt hoàn toàn từng thành phần năng lực thành các bài kiểm tra độc lập nhằm tránh sự mơ hồ khi định lượng.","D. YCCĐ và Nội dung giáo dục ứng với nhau theo quan hệ tuyến tính; mỗi bài học bắt buộc chỉ tập trung hình thành duy nhất một thành phần năng lực cốt lõi nhằm đảm bảo tính chính xác khi lượng hóa kết quả."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":18,"question":"Câu 8 (Vận dụng): Một giáo viên Tin học THPT được giao thiết kế bài tập dự án 6 tiết cho học sinh lớp 11 với mục tiêu: \"Học sinh viết được chương trình vận dụng kiến thức tích hợp liên môn để giải quyết vấn đề thực tiễn\". Trong điều kiện phòng máy tính của nhà trường chỉ có cấu hình trung bình và không có trang thiết bị phần cứng chuyên dụng (như Robot giáo dục, cảm biến), phương án tổ chức nào dưới đây giáo viên nên lựa chọn để đáp ứng tối đa tính mở, đúng mức độ YCCĐ và phù hợp thực tiễn?","options":["A. Ấn định bài toán \"Xử lý số liệu đo đạc Vật lý\" và yêu cầu tất cả học sinh sử dụng chung ngôn ngữ Python để đảm bảo tính nhất quán trong kiểm tra, đánh giá định kỳ của tổ chuyên môn.","B. Cho các nhóm học sinh tự đề xuất bài toán liên môn phù hợp, tự chọn ngôn ngữ lập trình hoặc môi trường phát triển, và đánh giá qua sản phẩm chạy thử cùng báo cáo quá trình hợp tác.","C. Yêu cầu học sinh lựa chọn các bài toán thuộc mạch Khoa học máy tính (CS) chuyên sâu và bắt buộc chứng minh tính đúng đắn logic của thuật toán trước khi triển khai chạy thử trên máy tính.","D. Chuyển nội dung dự án sang cho học sinh làm bài tập thực hành cá nhân trên phần mềm mô phỏng ảo để đảm bảo 100% học sinh đều đạt cùng một kết quả như nhau."],"correctIndex":1,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":19,"question":"Câu 9 (Vận dụng): Một nhóm giáo viên xây dựng kế hoạch dạy học chủ đề “Giải quyết vấn đề với sự trợ giúp của máy tính”. Nhóm dự kiến chỉ sử dụng kiến thức thuộc mạch Khoa học máy tính vì cho rằng đây là chủ đề gắn trực tiếp với thuật toán và lập trình. Khi lựa chọn nội dung và hoạt động, cách tổ chức nào sau đây phù hợp nhất với định hướng của chương trình?","options":["A. Xác định CS là mạch trọng tâm, đồng thời lựa chọn thêm một số kiến thức ICT và DL khi chúng trực tiếp phục vụ nhiệm vụ học tập.","B. Kết hợp DL, ICT và CS trong cùng chủ đề, nhưng phân chia thành các hoạt động riêng để học sinh lần lượt hoàn thành từng mạch kiến thức.","C. Xây dựng nhiệm vụ theo vấn đề thực tiễn, trong đó học sinh chủ động huy động kiến thức phù hợp từ DL, ICT, CS và các môn học liên quan.","D. Lấy ICT làm nền tảng của hoạt động, sau đó bổ sung kiến thức CS và DL tùy theo yêu cầu của từng nhiệm vụ."],"correctIndex":2,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":20,"question":"Câu 10 (Vận dụng): Tình huống: Trong dự án học tập môn Tin học lớp 9 (Chủ đề D: Đạo đức, pháp luật và văn hoá trong môi trường số), một nhóm học sinh đã tự ý thu thập các hình ảnh cá nhân của các bạn trong trường mà chưa xin phép, sau đó cắt ghép thành video châm biếm đăng tải lên trang mạng xã hội với mục đích \"tuyên truyền an toàn mạng\". Nhận xét nào dưới đây giáo viên nên dùng để đánh giá đúng mức độ đáp ứng YCCĐ của nhóm HS đó?","options":["A. Đạt về sử dụng công cụ kĩ thuật số nâng cao nhưng chưa đạt về nhận biết các hình phạt vi phạm hành chính trong Luật An ninh mạng.","B. Chưa đạt về tạo lập sản phẩm số đa phương tiện nhưng đã đạt về trách nhiệm bảo vệ an toàn thông tin cộng đồng trên Internet.","C. Chưa đạt về kĩ thuật biên tập video chuyên nghiệp nhưng đã đạt về tuân thủ đầy đủ bản quyền nội dung thông tin trong môi trường số.","D. Đạt về tạo ra sản phẩm số có tính truyền thông nhưng chưa đạt về bảo đảm sản phẩm số không vi phạm đạo đức và quyền riêng tư cá nhân."],"correctIndex":3,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":21,"question":"Câu 1 (Nhận biết): Theo Chương trình GDPT 2018 môn Tin học, phương pháp dạy học nào sau đây giữ vai trò đặc biệt quan trọng trong các chủ đề thuộc định hướng Tin học ứng dụng (ICT) ở cấp THPT?","options":["A. Phương pháp dạy học thực hành.","B. Phương pháp dạy học nêu và giải quyết vấn đề.","C. Phương pháp thuyết trình một chiều.","D. Phương pháp đàm thoại tái hiện."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":22,"question":"Câu 2 (Nhận biết): Theo Chương trình môn Tin học 2018, phương pháp dạy học nào sau đây được xác định là đặc biệt phù hợp với nhiều chủ đề của định hướng Khoa học máy tính (CS) ở cấp THPT nhằm phát triển tư duy máy tính cho học sinh?","options":["A. Thực hành.","B. Nêu và giải quyết vấn đề.","C. Theo dự án.","D. Theo tình huống."],"correctIndex":1,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":23,"question":"Câu 3 (Nhận biết): Trong mục tiêu đánh giá của chương trình môn Tin học, nội dung nào sau đây được xác định là thông tin cần cung cấp để hướng dẫn hoạt động học tập và điều chỉnh hoạt động dạy học?","options":["A. Mức độ đáp ứng yêu cầu cần đạt và sự tiến bộ của học sinh.","B. Số lượng kiến thức học sinh ghi nhớ sau mỗi bài học.","C. Số lượng bài tập học sinh hoàn thành trong mỗi chủ đề.","D. Thời gian học sinh sử dụng thiết bị và phần mềm trong học tập."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":24,"question":"Câu 4 (Thông hiểu): Phương án nào sau đây thể hiện mối quan hệ giữa nội dung bài học và việc lựa chọn phương pháp, hình thức tổ chức dạy học?","options":["A. Phương pháp dạy học được chọn trước, sau đó nội dung bài học được điều chỉnh cho phù hợp với phương pháp đó.","B. Nội dung bài học quyết định việc lựa chọn phương pháp và hình thức tổ chức dạy học phù hợp cho từng bài, từng hoạt động.","C. Nội dung bài học và phương pháp dạy học độc lập với nhau, còn hình thức tổ chức dạy học mới phụ thuộc vào nội dung.","D. Một phương pháp và một hình thức tổ chức dạy học cố định có thể áp dụng cho mọi nội dung bài học."],"correctIndex":1,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":25,"question":"Câu 5 (Thông hiểu): Nhận định nào sau đây thể hiện phù hợp nhất mối quan hệ giữa sản phẩm số và đánh giá trong dạy học Tin học?","options":["A. Căn cứ để đánh giá khả năng vận dụng kiến thức, kĩ năng của học sinh vào việc đáp ứng nhiệm vụ thực tế đặt ra.","B. Minh chứng bổ trợ, còn đánh giá chủ yếu dựa vào kiểm tra mức độ ghi nhớ kiến thức, kĩ năng riêng lẻ.","C. Căn cứ đánh giá ở các chủ đề thuộc mạch ICT, còn ở các mạch khác việc đánh giá không dựa vào sản phẩm số.","D. Được đánh giá chủ yếu qua mức độ đẹp, độc đáo về hình thức, không cần đối chiếu với yêu cầu của nhiệm vụ."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":26,"question":"Câu 6 (Thông hiểu): Phương pháp đo lường nào sau đây được áp dụng trong quá trình triển khai kiểm tra đánh giá kết quả giáo dục phổ thông theo Chương trình môn Tin học mới đối với các chủ đề học tập có nội dung trọng tâm thuộc mạch kiến thức Khoa học máy tính để bám sát bản chất và mục tiêu chính của nội dung?","options":["A. Quan sát thái độ, tình cảm và hành vi ứng xử cụ thể của các em khi tương tác trong môi trường số.","B. Đánh giá mức độ thành thạo các kĩ năng thao tác phần mềm nhằm tạo ra những sản phẩm ứng dụng.","C. Xem xét sự biểu hiện của năng lực sáng tạo và tư duy mang tính hệ thống trong giải quyết vấn đề.","D. Kiểm tra khả năng ghi nhớ chính xác các định nghĩa, quy trình hoặc một dãy lệnh lập trình đơn lẻ."],"correctIndex":2,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":27,"question":"Câu 7 (Thông hiểu): Khi dạy học theo định hướng Khoa học máy tính ở trung học phổ thông, phương pháp nào sau đây có thể phù hợp hơn với nhiều chủ đề và vì sao?","options":["A. Nêu và giải quyết vấn đề, vì tạo cơ hội cho học sinh mô hình hóa, thiết kế giải thuật và tìm lỗi.","B. Thực hành, vì tạo điều kiện cho học sinh thuần thục thao tác kỹ thuật trên các phần mềm ứng dụng.","C. Theo dự án, vì thúc đẩy học sinh tăng cường trải nghiệm quy trình tạo ra sản phẩm số hoàn chỉnh.","D. Theo tình huống, vì giúp học sinh nhận diện và phân tích sâu các quy tắc ứng xử trong không gian mạng."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":28,"question":"Câu 8 (Vận dụng): Khi tổ chức dạy học các nội dung lí thuyết và thuật toán ở môn Tin học, giáo viên nên lựa chọn phương pháp và cách sắp xếp không gian lớp học như thế nào nhằm tránh việc chỉ cho học sinh ngồi làm việc trên phòng máy hoặc bắt học thuộc các đoạn mã code, đồng thời giúp các em rèn luyện năng lực phân chia bài toán và tư duy hệ thống trước khi viết code?","options":["A. Yêu cầu học sinh ngồi trực tiếp ở phòng máy tính, vừa quan sát video mô phỏng sơ đồ khối vừa gõ code và áp dụng phương pháp thử - sai liên tục để tự khắc phục lỗi cú pháp.","B. Chia nhóm học sinh tại phòng thực hành để tự nghiên cứu các đoạn mã nguồn mở trên Internet, sau đó vẽ sơ đồ tư duy trên bảng nhóm nhằm hình thành năng lực tư duy hệ thống.","C. Lựa chọn không gian phòng lý thuyết, kết hợp dùng hình ảnh và video minh họa để dẫn dắt học sinh thực hiện các thao tác tư duy, mô hình hóa giải thuật trước khi viết code.","D. Tổ chức dạy học đan xen giữa hai không gian, yêu cầu học sinh ghi nhớ cấu trúc mẫu của thuật toán rồi thực hiện tái hiện lại quy trình tư duy bằng những bài tập trên giấy."],"correctIndex":2,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":29,"question":"Câu 9 (Vận dụng):  Để đánh giá định kỳ kết quả học tập dự án liên môn thuộc chủ đề \"Ứng dụng Tin học\" (ICT) lớp 11 trong điều kiện nhà trường thiếu hụt thiết bị thực hành chuyên dụng và sĩ số lớp đông, việc kết hợp các hình thức, công cụ kiểm tra nào sau đây giúp bảo đảm tính khách quan, đo lường đúng thành phần năng lực mà KHÔNG gây áp lực quá tải cho giáo viên?","options":["A. Bài kiểm tra thực hành cá nhân tại phòng máy kết hợp hồ sơ học tập lưu trữ toàn bộ lịch sử thao tác phần mềm của từng học sinh.","B. Sản phẩm số của nhóm kết hợp bảng đánh giá đồng đẳng giữa các thành viên và phiếu đánh giá tiêu chí sản phẩm của giáo viên.","C. Bài thi viết kết hợp lý thuyết - bài tập tự luận và phỏng vấn trực tiếp từng nhóm học sinh về quy trình thiết kế sản phẩm.","D. Báo cáo chuyên đề của nhóm kết hợp bài kiểm tra trắc nghiệm chuẩn hóa nhằm đo lường chính xác lượng kiến thức lý thuyết tích lũy."],"correctIndex":1,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":30,"question":"Câu 10 (Vận dụng): Trong quá trình hướng dẫn dự án học tập thuộc định hướng Khoa học máy tính (CS) lớp 11, giáo viên ghi nhận một nhóm học sinh đã xây dựng được sản phẩm phần mềm chạy thực nghiệm đáp ứng tương đối tốt yêu cầu thực tế, tuy nhiên thuật toán cốt lõi do nhóm đề xuất vẫn còn hạn chế và chưa tối ưu về mặt logic. Quyết định xử lý sư phạm nào sau đây thể hiện đúng nhất nguyên tắc đánh giá vì sự tiến bộ và phát triển tư duy máy tính cho học sinh?","options":["A. Ghi nhận kết quả thực nghiệm của sản phẩm số, đồng thời tổ chức cho học sinh phân tích điểm nghẽn logic để cải tiến và tối ưu hóa thuật toán qua tiến trình phát triển lặp.","B. Yêu cầu nhóm tạm dừng việc thực thi phần mềm, tập trung chứng minh tính đúng đắn và độ phức tạp tính toán của thuật toán trên lý thuyết trước khi cho phép tiếp tục lập trình.","C. Khái quát hóa kết quả đầu ra thực tế và đánh giá ở mức tối đa nhằm khuyến khích tính sáng tạo, chấp nhận bỏ qua việc tối ưu thuật toán do sản phẩm đã giải quyết được bài toán thực tiễn.","D. Định hướng nhóm thay thế cấu trúc hiện tại bằng thuật toán chuẩn do giáo viên cung cấp nhằm tái cấu trúc lại chương trình, bảo đảm tính chính xác tuyệt đối và đúng tiến độ dự án."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":31,"question":"Câu 1 (Nhận biết): Khi xây dựng kế hoạch giáo dục nhà trường, phương án nào sau đây thể hiện ý nghĩa của việc căn cứ vào điều kiện thực tiễn của nhà trường và địa phương?","options":["A. Giúp nhà trường chủ động điều chỉnh nội dung và phương pháp giáo dục để phù hợp với nhu cầu của học sinh, không nhất thiết phải thực hiện đầy đủ các yêu cầu của chương trình GDPT.","B. Giúp nhà trường lựa chọn những nội dung giáo dục phù hợp với điều kiện thực tế, đồng thời bảo đảm thực hiện mục tiêu và yêu cầu của chương trình GDPT.","C. Giúp nhà trường thống nhất nội dung và phương pháp giáo dục giữa các lớp, hạn chế sự khác biệt trong tổ chức dạy học của giáo viên.","D. Giúp nhà trường ưu tiên sử dụng các nguồn lực hiện có để tổ chức hoạt động giáo dục, từ đó giảm bớt những nội dung chưa phù hợp với điều kiện địa phương."],"correctIndex":1,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":32,"question":"Câu 2 (Nhận biết): Theo Chương trình giáo dục phổ thông 2018 cấp THPT, hoạt động nào sau đây KHÔNG phải là loại hình tổ chức chủ yếu của Hoạt động trải nghiệm, hướng nghiệp?","options":["A. Sinh hoạt dưới cờ.","B. Sinh hoạt lớp.","C. Hoạt động giáo dục theo chủ đề.","D. Hoạt động phụ đạo học sinh."],"correctIndex":3,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":33,"question":"Câu 3 (Nhận biết): Mục tiêu cốt lõi nào sau đây được xác định khi nhà trường thực hiện việc xây dựng và tổ chức triển khai kế hoạch giáo dục nhằm phát huy tính chủ động, sáng tạo của tổ chuyên môn và giáo viên?","options":["A. Sử dụng hiệu quả cơ sở vật chất, thiết bị dạy học nhằm đáp ứng các yêu cầu thực hiện phương pháp dạy học và kiểm tra, đánh giá theo hướng phát triển phẩm chất, năng lực học sinh.","B. Chuẩn hóa cấu trúc phân phối chương trình thành một hệ thống dữ liệu số dùng chung để áp dụng đồng loạt nhằm giảm tải áp lực hồ sơ cho toàn bộ giáo viên trong toàn cấp học.","C. Xây dựng một khung phân phối thời gian cứng nhắc cho tất cả các môn học nhằm tối ưu hóa quy trình kiểm kê tài sản định kỳ hàng năm của tổ chuyên môn phục vụ công tác thanh tra.","D. Tối ưu hóa quy trình quản lý hành chính và tài chính nội bộ nhằm bảo toàn tuổi thọ của trang thiết bị kỹ thuật cao do nhà trường trực tiếp quản lý và phân bổ."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":34,"question":"Câu 4 (Thông hiểu): Phương án giải quyết nào sau đây được hiệu trưởng chỉ đạo áp dụng đối với các môn học có số tiết ít trong trường hợp nhà trường gặp khó khăn nghiêm trọng về việc thiếu giáo viên hoặc thiếu cơ sở vật chất ở những năm đầu triển khai chương trình?","options":["A. Cắt giảm hoàn toàn thời lượng của môn học đó khỏi khung kế hoạch giáo dục năm học và chuyển đổi thành hình thức hoạt động tự học ngoại khóa bắt buộc cho học sinh.","B. Bắt buộc phải chia đều chính xác số tiết cho tất cả 35 tuần của năm học nhằm đảm bảo tính đồng bộ hình thức giống như các môn học chính diện khác trong nhà trường.","C. Linh hoạt bố trí dạy học theo từng một phần hai học kì nhưng vẫn phải bảo đảm chương trình môn học được thực hiện đầy đủ trong cả hai học kì.","D. Yêu cầu giáo viên bộ môn tự biên soạn lại toàn bộ nội dung kiến thức thành tài liệu tóm tắt để học sinh tự nghiên cứu tại nhà thay vì tổ chức các giờ lên lớp trực tiếp."],"correctIndex":2,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":35,"question":"Câu 5 (Thông hiểu): Nội dung và trình tự tiến hành nào sau đây được đặt ra trong bước sinh hoạt tổ/nhóm chuyên môn dựa trên nghiên cứu bài học để phân tích, rút kinh nghiệm giờ dạy theo đúng hướng dẫn?","options":["A. Đánh giá xếp loại thi đua trực tiếp của giáo viên đứng lớp; kiểm tra số lượng học sinh vắng mặt và tổng hợp điểm số kiểm tra miệng ngay tại lớp để báo cáo hiệu trưởng.","B. Mô tả hành động của học sinh; đánh giá kết quả học tập; phân tích nguyên nhân; đưa ra biện pháp khắc phục hạn chế và hoàn thiện kế hoạch dạy học.","C. Thống kê toàn bộ lỗi cú pháp hoặc lỗi trình bày bảng của giáo viên; yêu cầu viết bản kiểm điểm rút kinh nghiệm và nộp về ban giám hiệu trước cuối tuần.","D. Lấy ý kiến biểu quyết bằng phiếu kín của toàn bộ học sinh trong lớp về phong cách giảng dạy của giáo viên dự giờ để làm căn cứ đánh giá chuẩn nghề nghiệp."],"correctIndex":1,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":36,"question":"Câu 6 (Thông hiểu): Trong quá trình thực hiện kế hoạch dạy học môn Tin học, một tổ chuyên môn nhận thấy một số nội dung chưa đáp ứng đặc điểm và nhu cầu học tập của học sinh. Sau khi xem xét kết quả triển khai, tổ đề xuất điều chỉnh cách tổ chức dạy học cho những giai đoạn tiếp theo. Phương án nào sau đây thể hiện đúng yêu cầu đối với việc xây dựng kế hoạch giáo dục nhà trường qua tình huống trên?","options":["A. Điều chỉnh kế hoạch dựa trên kết quả thực hiện và tình hình thực tế.","B. Bổ sung nội dung dạy học theo nhu cầu và khả năng của học sinh.","C. Thay đổi phương pháp giảng dạy theo năng lực của đội ngũ giáo viên.","D. Phân bổ lại nguồn lực theo điều kiện thực tế của nhà trường."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":37,"question":"Câu 7 (Thông hiểu): Khi xây dựng kế hoạch giáo dục của nhà trường theo định hướng phát triển phẩm chất, năng lực học sinh, phương án nào sau đây thể hiện đúng ý nghĩa của việc xây dựng kế hoạch này?","options":["A. Cụ thể hóa chương trình giáo dục quốc gia dựa trên điều kiện thực tiễn và đặc điểm của nhà trường.","B. Điều chỉnh chương trình giáo dục quốc gia theo nhu cầu riêng của nhà trường và ưu tiên những nội dung phù hợp với điều kiện tổ chức dạy học.","C. Xây dựng kế hoạch giáo dục dựa trên định hướng chung của chương trình, đồng thời tăng cường quyền chủ động của giáo viên trong lựa chọn nội dung và phương pháp dạy học.","D. Phân bổ nội dung và hoạt động giáo dục theo điều kiện thực tế, chú trọng những yêu cầu phù hợp với đặc điểm của học sinh và địa phương."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":38,"question":"Câu 8 (Vận dụng): Một trường THPT khi xây dựng kế hoạch dạy học môn Tin học nhận thấy nguyện vọng lựa chọn môn học của học sinh khá đa dạng. Trong khi đó, số lượng giáo viên và phòng học bộ môn của trường chưa đáp ứng đồng đều cho tất cả các phương án. Nếu là người tham gia xây dựng kế hoạch, cách xử lí nào dưới đây phù hợp nhất?","options":["A. Ưu tiên phương án thuận lợi cho nhà trường, sau đó điều chỉnh nguyện vọng lựa chọn môn học của học sinh.","B. Khảo sát nguyện vọng của học sinh, đồng thời đối chiếu điều kiện nhà trường để xây dựng phương án phù hợp.","C. Xác định phương án tổ chức môn học dựa trên nguồn lực hiện có, sau đó khảo sát mức độ phù hợp với học sinh.","D. Tổng hợp nguyện vọng của học sinh, ưu tiên những môn có nhiều lựa chọn để bố trí nguồn lực trước."],"correctIndex":1,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":39,"question":"Câu 9 (Vận dụng): Khi xây dựng kế hoạch dạy học môn Tin học cấp THCS cho năm học mới, Tổ chuyên môn Tin học trường THCS X gặp khó khăn do thời lượng chương trình quy định cho mỗi khối lớp chỉ có 35 tiết/năm học (trung bình 1 tiết/tuần). Để giải quyết bài toán thời lượng ngắn nhưng vẫn đảm bảo học sinh đạt đủ yêu cầu cần đạt của 7 chủ đề xuyên suốt, đồng thời tăng cường trải nghiệm thực hành và giáo dục STEM theo định hướng phát triển năng lực, các giáo viên trong tổ đã đưa ra nhiều đề xuất khác nhau về việc phân phối thời lượng, hình thức tổ chức dạy học và kiểm tra đánh giá trong kế hoạch giáo dục của tổ chuyên môn. Phương án phân phối kế hoạch dạy học và tổ chức thực hiện nào dưới đây thể hiện sự vận dụng đúng đắn, linh hoạt các định hướng của Chương trình môn Tin học 2018?","options":["A. Duy trì phân bổ đều đặn 1 tiết/tuần xuyên suốt 35 tuần của năm học; tách rời tuần dạy lý thuyết tại lớp và tuần thực hành tại phòng máy, kết hợp kiểm tra viết trắc nghiệm trên giấy để đảm bảo quản lý nề nếp và tiến độ.","B. Chủ động xây dựng các bài học tích hợp liên môn, linh hoạt xếp tiết đôi cho giờ thực hành/dự án, đồng thời lồng ghép đánh giá sản phẩm số và đánh giá đồng đẳng trong quá trình học.","C. Bám sát cấu trúc bài học và khung thời lượng gợi ý trong sách giáo khoa; kết hợp giảng giải lý thuyết với hướng dẫn thực hành ngắn trong từng tiết 45 phút để bảo đảm tiến độ.","D. Tập trung trang bị nền tảng lý thuyết trên lớp; hướng dẫn học sinh tự thực hành bài tập ứng dụng và hoàn thiện sản phẩm dự án tại nhà để giảm tải áp lực cho phòng máy."],"correctIndex":1,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":40,"question":"Câu 10 (Vận dụng): Sau học kỳ I, một trường THPT nhận thấy các hoạt động giáo dục được triển khai đúng tiến độ nhưng học sinh còn hạn chế trong việc vận dụng kiến thức vào thực tiễn. Qua phản hồi của giáo viên và học sinh, nhà trường phát hiện một số bất cập về thời lượng, thiết bị dạy học và sự phối hợp giữa các tổ chuyên môn. Trong quá trình xây dựng kế hoạch giáo dục cho học kỳ II, phương án nào sau đây thể hiện cách xử lý phù hợp nhất?","options":["A. Rà soát kết quả học tập, tăng cường kiểm tra năng lực vận dụng và giữ ổn định kế hoạch hiện hành để bảo đảm tính thống nhất giữa các tổ chuyên môn.","B. Điều chỉnh thời lượng và bổ sung thiết bị theo đề xuất của từng tổ chuyên môn, đồng thời trao quyền chủ động cho các tổ quyết định nội dung triển khai phù hợp với tình hình thực tế.","C. Tổng hợp phản hồi của giáo viên và học sinh, ưu tiên khắc phục những hạn chế về cơ sở vật chất, đồng thời duy trì tiến độ đã xác định để tránh ảnh hưởng đến việc thực hiện chương trình.","D. Đánh giá quá trình triển khai, xác định nguyên nhân của những bất cập và điều chỉnh nội dung, thời lượng, cách phối hợp cùng nguồn lực trên cơ sở thực tế, bảo đảm mục tiêu chương trình giáo dục."],"correctIndex":3,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":41,"question":"Câu 1 (Nhận biết): Phương án nào sau đây thể hiện mục tiêu khi xây dựng kế hoạch giáo dục tổ chuyên môn?","options":["A. Phát triển của tổ chuyên môn và nhà trường, đáp ứng yêu cầu của CTGDPT.","B. Thi đua của đội ngũ giáo viên, nâng cao thành tích giảng dạy trong năm học.","C. Nâng cao kết quả học tập của học sinh, chú trọng nhóm học sinh có thành tích tốt.","D. Tổ chức hoạt động ngoại khóa, tăng cường phong trào thi đua trong nhà trường."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":42,"question":"Câu 2 (Nhận biết): Khi xây dựng kế hoạch giáo dục của tổ chuyên môn, yêu cầu nào sau đây thể hiện việc đảm bảo tính khả thi?","options":["A. Đặc điểm học sinh, tình hình đội ngũ giáo viên và điều kiện cơ sở vật chất của nhà trường.","B. Sắp xếp các bài học theo trình tự thời gian phù hợp với kế hoạch chung của nhà trường.","C. Điều chỉnh linh hoạt nội dung và thời gian thực hiện khi tình hình thực tiễn thay đổi.","D. Xây dựng kế hoạch dựa trên các căn cứ pháp lý và các kế hoạch cấp cao hơn."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":43,"question":"Câu 3 (Nhận biết): Hai kế hoạch thành phần nào sau đây thuộc Kế hoạch giáo dục của tổ chuyên môn mà giáo viên cần xác định khi nghiên cứu hướng dẫn về cấu trúc hồ sơ chuyên môn của Bộ Giáo dục và Đào tạo?","options":["A. Dạy học môn học và tổ chức các hoạt động giáo dục.","B. Giáo dục nhà trường và bài dạy của giáo viên bộ môn.","C. Bồi dưỡng học sinh giỏi và kiểm tra đánh giá định kỳ.","D. Phụ đạo học sinh yếu và sinh hoạt chuyên môn theo tuần."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":44,"question":"Câu 4 (Thông hiểu): Phương án nào sau đây thể hiện đúng việc thực hiện yêu cầu bảo đảm tính linh hoạt trong xây dựng kế hoạch giáo dục của tổ chuyên môn mà cán bộ quản lý và giáo viên cần nắm vững?","options":["A. Chủ động điều chỉnh nội dung, thời lượng và tiến độ thực hiện khi điều kiện thực tế có sự thay đổi.","B. Điều chỉnh giảm bớt các nội dung lý thuyết nhằm gia tăng thời lượng cho các bài học thực hành.","C. Thay đổi các yêu cầu cần đạt của chương trình môn học cho phù hợp với trình độ nhận thức của học sinh","D. Thực hiện điều chỉnh tiến độ dạy học khi có văn bản hướng dẫn bổ sung của cấp trên."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":45,"question":"Câu 5 (Thông hiểu): Phương án nào sau đây thể hiện Mối quan hệ giữa kế hoạch giáo dục của tổ chuyên môn và kế hoạch giáo dục cá nhân của giáo viên?","options":["A. Kế hoạch cá nhân được xây dựng độc lập, không phụ thuộc vào kế hoạch chung của tổ chuyên môn.","B. Kế hoạch của tổ chuyên môn làm căn cứ để giáo viên xây dựng kế hoạch cá nhân theo nhiệm vụ được phân công.","C. Kế hoạch cá nhân của giáo viên là căn cứ để tổ chuyên môn xây dựng kế hoạch chung phù hợp với nhiệm vụ giảng dạy.","D. Kế hoạch của tổ chuyên môn thay thế kế hoạch cá nhân, giúp giáo viên thực hiện nhiệm vụ giảng dạy trong năm học."],"correctIndex":1,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":46,"question":"Câu 6 (Thông hiểu): Phương án nào sau đây nêu đúng căn cứ quan trọng nhất để định lượng thời gian (số tiết) cho một bài học trong kế hoạch giáo dục môn học?","options":["A. Số lượng và mức độ phức tạp của các yêu cầu cần đạt trong chương trình.","B. Đặc điểm tâm sinh lý và mức độ hứng thú của học sinh đối với mạch kiến thức.","C. Điều kiện cơ sở vật chất và các thiết bị dạy học hiện có của nhà trường.","D. Dung lượng và cấu trúc các mạch nội dung trong sách giáo khoa đã chọn."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":47,"question":"Câu 7 (Thông hiểu): Nguyên tắc chủ yếu nào sau đây cần được giáo viên căn cứ khi tiến hành cấu trúc lại nội dung để xây dựng thành các bài học hoặc chủ đề dạy học trong kế hoạch của tổ chuyên môn?","options":["A. Bảo đảm tính logic của mạch kiến thức và tính trọn vẹn của vấn đề học tập.","B. Trình tự các bài học trong sách giáo khoa nhằm bảo đảm tính hệ thống của chương trình.","C. Ưu tiên tích hợp tối đa các kiến thức liên môn nhằm mở rộng phạm vi ứng dụng thực tiễn.","D. Phân chia đều đặn khối lượng nội dung kiến thức tương ứng với số tiết định mức của từng tuần."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":48,"question":"Câu 8 (Vận dụng): Khi đối chiếu bảng yêu cầu cần đạt của chủ đề \"Đạo đức, pháp luật và văn hóa trong môi trường số\" với sách giáo khoa đang sử dụng, tổ chuyên môn phát hiện có một yêu cầu cần đạt về bảo vệ tài khoản cá nhân nhưng sách giáo khoa không có bài học hay hoạt động nào tương ứng. Phương án nào sau đây là cách xử lý đúng theo hướng dẫn thực hiện chương trình?","options":["A. Điều chỉnh trọng tâm các bài học liên quan, ưu tiên nội dung đã có trong sách giáo khoa và lồng ghép yêu cầu còn thiếu khi có điều kiện.","B. Thiết kế nội dung hoặc hoạt động dạy học bổ sung, xác định thời lượng và tích hợp vào kế hoạch giáo dục của tổ chuyên môn.","C. Bổ sung yêu cầu còn thiếu vào kế hoạch kiểm tra, đánh giá để học sinh tự củng cố kiến thức trong quá trình học tập.","D. Phân công giáo viên phụ trách chủ đề hướng dẫn học sinh tự tìm hiểu, đồng thời dành thời gian trên lớp để giải đáp thắc mắc phát sinh."],"correctIndex":1,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":49,"question":"Câu 9 (Vận dụng): Khi các thành viên trong tổ chuyên môn Tin học tiến hành sinh hoạt chuyên môn để triển khai bước xây dựng phân phối chương trình trong khung kế hoạch dạy học hằng năm theo đúng các định hướng chỉ đạo về việc cụ thể hóa chương trình tổng thể và chương trình môn học trong bối cảnh quỹ thời lượng định mức giới hạn dành cho cấp trung học phổ thông, phương án nào sau đây phản ánh đúng bản chất của phương pháp xác định định mức số tiết cho từng bài học cụ thể nhằm bảo đảm tính khoa học và hiệu quả sư phạm?","options":["A. Căn cứ trên tổng số lượng thời lượng quy định cho môn học kết hợp với tỷ lệ phân bổ của các mạch nội dung lớn, từ đó đối chiếu với các yêu cầu cần đạt cùng mức độ phức tạp nhận thức để cân đối thời lượng phù hợp.","B. Dựa trên số lượng trang tài liệu in ấn và dung lượng hệ thống bài tập thực hành kèm theo trong chương mục sách giáo khoa để thực hiện việc quy đổi định mức thời lượng theo tỷ lệ tuyến tính tương ứng cho mỗi bài học.","C. Áp dụng phương thức đồng hóa số lượng tiết học giữa các bài học trong cùng một chủ đề kiến thức nhằm duy trì sự tương thích về mặt thời gian biểu thực hiện giữa các tổ chuyên môn khác nhau theo định hướng chung.","D. Xuất phát từ việc đánh giá năng lực tiếp thu thực tế của đối tượng học sinh tại từng cơ sở giáo dục để chủ động điều chỉnh tăng cường tỷ trọng số lượng tiết học thực hành nhằm bù đắp thời lượng lý thuyết."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":50,"question":"Câu 10 (Vận dụng): Trong quá trình tổ chức sinh hoạt chuyên môn nhằm hoạch định bản kế hoạch chi tiết để triển khai các hoạt động giáo dục ngoài giờ lên lớp như tham quan cơ sở sản xuất, câu lạc bộ học thuật hay cắm trại trải nghiệm theo đúng định hướng phát triển phẩm chất và năng lực người học, phương án nào sau đây phản ánh đúng yêu cầu về cách thức xác định thời điểm, địa điểm cùng các điều kiện bảo đảm thực hiện?","options":["A. Lựa chọn các địa điểm tổ chức trong khuôn viên nhà trường hoặc địa điểm nổi tiếng tại địa phương nhằm bảo đảm tính an toàn, giảm thiểu nguy cơ phát sinh rủi ro và đơn giản hóa các thủ tục hành chính khi trình cấp trên phê duyệt.","B. Phân chia thời điểm và số lượng hoạt động giáo dục đều đặn giữa các tháng trong năm học dựa trên lịch phân công công tác của giáo viên để dễ dàng sắp xếp công việc và không gây quá tải cho tổ chuyên môn.","C. Sắp xếp thời điểm tổ chức tập trung vào các đợt phát động thi đua cao điểm chào mừng ngày lễ lớn của ngành nhằm phục vụ công tác truyền thông, thu thập minh chứng và lập báo cáo thành tích thi đua cho nhà trường.","D. Xác lập thời điểm bảo đảm liên kết logic chặt chẽ với tiến trình truyền thụ mạch kiến thức môn học, kết hợp khoanh vùng địa điểm phù hợp kèm phân định rõ trách nhiệm chủ trì, phối hợp và các điều kiện cơ sở vật chất."],"correctIndex":3,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":51,"question":"Câu 1 (Nhận biết): Khi trình bày cấu trúc kế hoạch bài dạy theo định hướng phát triển phẩm chất và năng lực học sinh, phương án nào sau đây nêu đúng các thành phần cơ bản?","options":["A. Mục tiêu, thiết bị dạy học và học liệu, tiến trình dạy học.","B. Phân phối chương trình; lịch kiểm tra; kết quả học tập của lớp.","C. Nội dung sách giáo khoa; danh sách học sinh; bảng điểm môn học.","D. Kế hoạch năm học; lịch công tác; báo cáo chuyên môn của tổ."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":52,"question":"Câu 2 (Nhận biết): Phương án nào sau đây phản ánh đúng bản chất của việc thiết lập môi trường dạy học phù hợp khi giáo viên tiến hành phân tích các vai trò chuyên môn của bản kế hoạch bài dạy trong công tác chuẩn bị trước khi lên lớp nhằm đảm bảo tiến trình tổ chức các hoạt động học tập cho học sinh đạt hiệu quả?","options":["A. Xác định các mục tiêu dạy học từ trước kết hợp định hình những chiến lược giảng dạy, phương pháp cùng phương tiện hỗ trợ nhằm đảm bảo thực hiện tốt các mục tiêu giáo dục.","B. Xây dựng một biểu mẫu hành chính chung và các giáo viên bộ môn thường áp dụng trong nhiều tiết lên lớp nhằm đồng bộ hóa hồ sơ chuyên môn tại các cơ sở giáo dục phổ thông.","C. Cho phép giáo viên lược bỏ các yêu cầu cần đạt của chương trình tổng thể để tập trung nhiều hơn vào việc luyện giải các dạng bài tập nâng cao dành cho đội ngũ học sinh giỏi cấp trường.","D. Thực hiện giao quyền điều hành tiến trình tổ chức các hoạt động học tập trên lớp cho ban cán sự lớp tự quản lý dưới sự giám sát của ban đại diện phụ huynh học sinh."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":53,"question":"Câu 3 (Nhận biết): Khi thiết kế tiến trình dạy học cho một bài Tin học, phương án nào sau đây thể hiện đúng trình tự chuỗi hoạt động học tập thường được sử dụng?","options":["A. Mở đầu – luyện tập – hình thành kiến thức – vận dụng.","B. Mở đầu – hình thành kiến thức – luyện tập – vận dụng.","C. Hình thành kiến thức – mở đầu – vận dụng – luyện tập.","D. Luyện tập – hình thành kiến thức – mở đầu – vận dụng."],"correctIndex":1,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 4","level":"NB","levelName":"Nhận biết"},
{"id":54,"question":"Câu 4 (Thông hiểu): Sau khi xây dựng kế hoạch bài dạy, giáo viên nhận thấy mục tiêu đã bao quát yêu cầu cần đạt nhưng quỹ thời gian dành cho luyện tập chưa đáp ứng yêu cầu để học sinh hoàn thành nhiệm vụ. Phương án nào sau đây thể hiện cách xử lí phù hợp nhất khi hoàn thiện kế hoạch bài dạy?","options":["A. Điều chỉnh thời lượng và các hoạt động học tập.","B. Giữ nguyên thời lượng và thực hiện theo kế hoạch ban đầu.","C. Bổ sung mục tiêu mới và giữ nguyên các hoạt động đã thiết kế.","D. Chuyển hoạt động luyện tập thành nhiệm vụ tự học ngoài lớp."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":55,"question":"Câu 5 (Thông hiểu): Trong một tiết Tin học, các nhóm học sinh hoàn thành nhiệm vụ lập trình với những kết quả khác nhau. Một số chương trình chạy đúng nhưng phần giải thích còn hạn chế, trong khi một số nhóm đưa ra cách giải quyết khác nhau nhưng vẫn đáp ứng yêu cầu. Để khai thác tốt kết quả học tập và giúp học sinh hiểu rõ hơn bản chất của vấn đề, phương án nào sau đây phù hợp nhất với định hướng xây dựng kế hoạch bài dạy phát triển năng lực?","options":["A. Ưu tiên giới thiệu chương trình mẫu hoàn chỉnh, sau đó yêu cầu cả lớp đối chiếu sản phẩm của nhóm mình với lời giải chuẩn để tự điều chỉnh những điểm chưa chính xác.","B. Tổ chức cho các nhóm trình bày cách giải quyết, đặt câu hỏi làm rõ sự khác biệt giữa các sản phẩm, sau đó phân tích kết quả và xác định những kiến thức, kĩ năng cần hoàn thiện.","C. Khuyến khích các nhóm đổi sản phẩm để nhận xét lẫn nhau theo tiêu chí có sẵn, tổng hợp kết quả đánh giá và chuyển sang nhiệm vụ mới khi phần lớn sản phẩm đã đạt yêu cầu.","D. Dành thêm thời gian để từng nhóm sửa lỗi chương trình, kiểm tra khả năng thực thi trên máy tính và căn cứ vào sản phẩm cuối cùng để xác định mức độ hoàn thành của từng nhóm."],"correctIndex":1,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":56,"question":"Câu 6 (Thông hiểu): Khi xem xét một bản kế hoạch bài dạy Tin học, tổ chuyên môn nhận thấy học sinh có thể hoàn thành các bài tập củng cố nhưng còn lúng túng khi gặp một tình huống mới. Mục tiêu của bài học lại hướng đến khả năng sử dụng kiến thức đã học để giải quyết vấn đề cụ thể. Phương án điều chỉnh nào sau đây thể hiện sự nhất quán hợp lý giữa mục tiêu, nội dung và cách tổ chức dạy học?","options":["A. Tăng độ phức tạp của các bài tập củng cố, đồng thời bổ sung câu hỏi yêu cầu giải thích cách làm để học sinh nâng cao khả năng phân tích và vận dụng kiến thức.","B. Rút ngắn phần hình thành kiến thức mới, dành phần thời gian còn lại cho học sinh thực hiện thêm các bài tập tương tự nhằm củng cố những nội dung trọng tâm.","C. Bổ sung nhiệm vụ giải quyết một tình huống thực tế, xác định sản phẩm cần đạt và cách đánh giá tương ứng, đồng thời điều chỉnh thời lượng để bảo đảm học sinh có cơ hội thực hiện nhiệm vụ.","D. Thay đổi hình thức trình bày kiến thức bằng sơ đồ trực quan và ví dụ minh họa, kết hợp kiểm tra cuối bài để xác định mức độ ghi nhớ và hiểu nội dung của học sinh."],"correctIndex":2,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":57,"question":"Câu 7 (Thông hiểu): Cách thể hiện nào sau đây đáp ứng đúng yêu cầu khi thiết kế tiến trình tổ chức hoạt động học trong Kế hoạch bài dạy của giáo viên?","options":["A. Tập trung mô tả hoạt động cụ thể của giáo viên và học sinh thay vì ghi chi tiết kịch bản lời thoại.","B. Xây dựng hệ thống câu hỏi kèm đáp án chi tiết cho từng nội dung để giáo viên chủ động điều hành tiến trình dạy học.","C. Liệt kê đầy đủ các thành phần năng lực chung và năng lực đặc thù cần đạt được trong mỗi hoạt động học riêng lẻ.","D. Bố trí các hoạt động học theo đúng trình tự xuất hiện của các nội dung kiến thức trình bày trong sách giáo khoa."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 4","level":"TH","levelName":"Thông hiểu"},
{"id":58,"question":"Câu 8 (Vận dụng): Trong quá trình xây dựng Kế hoạch bài dạy cho Bài 15: Hoàn thiện hình ảnh đồ họa (Chủ đề E – Ứng dụng tin học) môn Tin học lớp 10, khi đối mặt với tình huống học sinh trong lớp có sự phân hóa mạnh về kỹ năng sử dụng phần mềm, giáo viên nên lựa chọn phương án xử lý nào sau đây để thể hiện đúng nguyên tắc dạy học phân hóa và sử dụng hiệu quả công cụ kiểm tra đánh giá?","options":["A. Biên soạn bộ đề kiểm tra trắc nghiệm lý thuyết song song với bài thực hành nhằm hỗ trợ điểm số cho các nhóm học sinh gặp khó khăn về kỹ năng thao tác trên máy tính.","B. Xây dựng bảng tiêu chí đánh giá sản phẩm với nhiều mức độ đạt được rõ ràng, kết hợp thiết kế hệ thống nhiệm vụ mở rộng cho nhóm hoàn thành.","C. Điều chỉnh các tiêu chí kỹ thuật trong thang đánh giá dành riêng cho nhóm học sinh yếu để bảo đảm tính vừa sức và tạo động lực học tập.","D. Phân chia lại danh sách các nhóm theo cùng mức độ năng lực để áp dụng các yêu cầu kiểm tra đánh giá khác nhau cho từng đối tượng học sinh."],"correctIndex":1,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":59,"question":"Câu 9 (Vận dụng): Trong tiết thực hành dạy học thuật toán tìm kiếm Tin học 11, phòng máy tính bất ngờ mất kết nối mạng và một số máy không khởi động được phần mềm lập trình. Giáo viên nên lựa chọn phương án nào để linh hoạt điều chỉnh cách tổ chức hoạt động học tập, đồng thời bảo đảm mục tiêu phát triển tư duy thuật toán cho học sinh?","options":["A. Chia nhóm mô phỏng từng bước chạy thuật toán trên giấy A4 và đánh giá chéo kết quả.","B. Quan sát giáo viên thao tác mẫu trên máy chiếu và hoàn thành phiếu bài tập cá nhân.","C. Thảo luận nhóm để xây dựng sơ đồ khối chi tiết của thuật toán rồi thuyết trình trước lớp.","D. Tóm tắt lại các bước logic của thuật toán vào vở và giải các bài tập lý thuyết liên quan."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":60,"question":"Câu 10 (Vận dụng): Khi thiết kế KHBD bài “Thuật toán tìm kiếm tuần tự”, giáo viên đặt mục tiêu học sinh vận dụng thuật toán để giải quyết bài toán thực tế và tổ chức cho học sinh làm việc nhóm viết chương trình C++. Tuy nhiên, giáo viên chỉ sử dụng bài kiểm tra trắc nghiệm lý thuyết để đánh giá kết quả học tập. Nguyên tắc nào sau đây chưa được đảm bảo?","options":["A. Sự thống nhất giữa yêu cầu cần đạt và minh chứng dùng để đánh giá kết quả học tập.","B. Tính linh hoạt trong việc điều chỉnh phương pháp dạy học theo diễn biến thực tế của lớp học.","C. Sự phù hợp giữa thời lượng phân bổ cho các hoạt động với dung lượng kiến thức của bài học.","D. Sự kết hợp hợp lý giữa các hình thức tổ chức hoạt động học tập."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 4","level":"VD","levelName":"Vận dụng"},
{"id":61,"question":"Câu 1: (NB) Phương án nào sau đây mô tả đúng vị trí môn tin học ở cấp THPT theo chương trình GDPT 2018?","options":["A. Bắt buộc, có sự phân hóa theo hai định hướng.","B. Lựa chọn và bình đẳng với các môn học khác.","C. Ghép cơ học, kết hợp với Công nghệ và Nghệ thuật.","D. Bắt buộc, thuộc nhóm Công nghệ số định hướng nghề nghiệp."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":62,"question":"Câu 2: (NB) Theo Chương trình GDPT 2018, nội dung nào sau đây không thuộc mục tiêu chung của môn Tin học?","options":["A. Góp phần hình thành và phát triển các phẩm chất chủ yếu cùng năng lực chung được quy định trong Chương trình tổng thể.","B. Góp phần chủ yếu giúp học sinh hình thành và rèn luyện năng lực tin học thích ứng an toàn với cuộc sống số.","C. Mở rộng hiểu biết sâu sắc về các thành tựu công nghệ thông tin và truyền thông hiện đại của những nước tiên tiến.","D. Trang bị hệ thống học vấn tin học phổ thông thông qua ba mạch kiến thức cốt lõi hoà quyện là DL, ICT và CS."],"correctIndex":2,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":63,"question":"Câu 3: (NB) Trong Chương trình Giáo dục phổ thông môn Tin học 2018, nội dung môn học được phát triển trên ba mạch kiến thức nào sau đây?","options":["A. Học vấn số hoá phổ thông (DL), Tin học ứng dụng, Khoa học máy tính (CS).","B. Học vấn số hoá phổ thông (DL), Công nghệ thông tin và truyền thông (ICT), Khoa học máy tính (CS).","C. Công nghệ thông tin và truyền thông (ICT), Khoa học máy tính (CS), Giải quyết vấn đề với sự trợ giúp của máy tính.","D. Học vấn số hoá phổ thông (DL), Công nghệ thông tin và truyền thông (ICT), Hướng nghiệp với tin học."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":64,"question":"Câu 4: (TH) Vì sao quan điểm đồng nhất việc học Tin học với việc học sử dụng máy tính và phần mềm là chưa chính xác?","options":["A. Sử dụng phần mềm thuộc mạch Ứng dụng tin học, trong khi mục tiêu cốt lõi của môn học là đào tạo chuyên sâu về kĩ thuật lập trình.","B. Sử dụng máy tính và phần mềm chỉ là một phần; Tin học còn phát triển tư duy máy tính và năng lực giải quyết vấn đề.","C. Kĩ năng thao tác trên các phần mềm ứng dụng hiện nay đã được tích hợp và chuyển giao cho môn Công nghệ đảm nhiệm.","D. Phần mềm thay đổi nhanh, còn Tin học cần ưu tiên các nguyên lí và phương pháp giải quyết vấn đề có tính ổn định."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":65,"question":"Câu 5: (TH) Phương án nào sau đây thể hiện đúng sự phát triển nâng cao về mục tiêu tư duy giải quyết vấn đề từ cấp trung học cơ sở lên cấp trung học phổ thông trong Chương trình môn Tin học?","options":["A. THCS giúp học sinh bước đầu làm quen với công nghệ số, còn THPT tập trung tạo ra và chia sẻ sản phẩm số đơn giản phục vụ học tập.","B. THCS trang bị kỹ năng biết chia một vấn đề lớn thành những nhiệm vụ nhỏ hơn, còn THPT yêu cầu kỹ thuật thiết kế thuật toán và tổ chức dữ liệu.","C. THCS yêu cầu học sinh hiểu biết cơ bản về hệ thống máy tính, còn THPT giúp học sinh đưa ra ý tưởng và chuyển giao nhiệm vụ cho máy tính thực hiện.","D. THCS dừng ở việc tạo ra và chia sẻ sản phẩm số đơn giản, còn THPT nâng cấp lên việc quen thuộc với các dịch vụ và phần mềm thông dụng hơn."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":66,"question":"Câu 6: (TH) Theo định hướng giáo dục STEM trong Chương trình giáo dục phổ thông môn Tin học 2018, phương án nào sau đây nêu đúng về vai trò và cách tiếp cận của môn Tin học?","options":["A. Vận dụng kiến thức Tin học để hỗ trợ các môn học khác trong quá trình xây dựng và trình bày sản phẩm STEM.","B. Khai thác công nghệ thông tin để giải quyết nhiệm vụ, qua đó tạo điều kiện phát triển năng lực vận dụng kiến thức.","C. Kết hợp kiến thức và kĩ năng Tin học với các lĩnh vực STEM nhằm giải quyết vấn đề và tạo ra sản phẩm phù hợp.","D. Tổ chức hoạt động Tin học theo các nhiệm vụ STEM, chú trọng vận dụng kiến thức vào những tình huống thực tiễn."],"correctIndex":2,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":67,"question":"Câu 7: (TH) Trong tiết thực hành Tin học, các nhóm học sinh chia sẻ sản phẩm số trên nền tảng học tập chung, nhận xét sản phẩm của nhóm khác theo tiêu chí do giáo viên cung cấp và điều chỉnh sản phẩm sau khi tiếp nhận phản hồi. Hoạt động trên của học sinh là minh chứng cho việc đạt được tiêu chuẩn cốt lõi nào dưới đây?","options":["A. NLa – Sử dụng và quản lí các phương tiện công nghệ thông tin và truyền thông.","B. NLb – Ứng xử phù hợp trong môi trường số.","C. NLd – Ứng dụng công nghệ thông tin và truyền thông trong học và tự học.","D. NLe – Hợp tác trong môi trường số."],"correctIndex":3,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":68,"question":"Câu 8: (VD) Trong buổi sinh hoạt chuyên môn nhằm thiết kế bài dạy tích hợp STEM cho học sinh THCS, các giáo viên trong tổ Tin học đưa ra các ý kiến khác nhau về định hướng xây dựng nội dung. Căn cứ vào quan điểm xây dựng Chương trình môn Tin học trong CTGDPT 2018, phương án nào sau đây là quan điểm sư phạm phù hợp?","options":["A. Tổ chức cho học sinh làm ra sản phẩm số có hàm lượng công nghệ để phát triển tư duy mô hình hóa và kỹ năng giải quyết vấn đề thực tế.","B. Hướng dẫn học sinh vận dụng thuần thục các phần mềm đồ họa và ứng dụng văn phòng nhằm chuẩn bị chu đáo báo cáo sản phẩm cho môn học khác.","C. Yêu cầu học sinh tích hợp trực tiếp các thư viện mã nguồn mở vào dự án để sản phẩm công nghệ có khả năng thương mại hóa trên thị trường.","D. Ưu tiên rèn luyện cho học sinh các kỹ thuật sửa lỗi và tối ưu hóa mã nguồn thuật toán để nâng cao năng lực lập trình độc lập của bộ môn."],"correctIndex":0,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":69,"question":"Câu 9: (VD) Một nhóm học sinh THCS tạo chương trình tính điểm trung bình của hai môn. Với điểm 8 và 6, chương trình hiển thị 8, trong khi kết quả cần là 7. Nhóm còn thời gian chỉnh sửa trước khi nộp. Phương án nào sau đây nên được thực hiện trước?","options":["A. Kiểm tra bước tính trung bình, sửa cách tính rồi chạy thử với dữ liệu khác.","B. Kiểm tra ô nhập dữ liệu, đổi cách hiển thị rồi chạy lại với hai điểm cũ.","C. Đổi bộ điểm thử nghiệm, ghi nhận kết quả mới rồi trình bày sản phẩm của nhóm.","D. Chọn phần mềm khác, nhập lại dữ liệu rồi đối chiếu giao diện giữa hai chương trình."],"correctIndex":0,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":70,"question":"Câu 10: (VD) Trong dự án STEM chế tạo \"Hệ thống chuông báo giờ tự động\" ở cấp THCS, mô hình của nhóm học sinh gặp sự cố: thiết bị vẫn đổ chuông vào hai ngày cuối tuần dù trường nghỉ học. Kiểm tra thực tế cho thấy các linh kiện phần cứng và vi mạch đều hoạt động bình thường. Để khắc phục triệt để sự cố này, giúp hệ thống vận hành đúng yêu cầu, giải pháp nào sau đây là phù hợp?","options":["A. Lập trình lại chức năng đồng bộ thời gian thực cho hệ thống thông qua kết nối với máy chủ mạng.","B. Thêm câu lệnh kiểm tra lịch làm việc vào chương trình để thiết bị tự động ngắt tín hiệu phát ra.","C. Bổ sung đoạn mã kích hoạt chế độ tiết kiệm năng lượng cho thiết bị sau giờ học chiều Thứ Sáu.","D. Viết thêm mô-đun kết nối với phần mềm lịch trên máy tính để nhận lệnh ngắt nguồn hàng tuần."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":71,"question":"Câu 1. (NB) Phương án nào sau đây là đúng về ba mạch kiến thức của môn Tin học theo chương trình GDPT 2018?","options":["A. Học vấn số hoá (DL), Công nghệ thông tin và truyền thông (ICT), Khoa học máy tính (CS).","B. Công nghệ thông tin và truyền thông (ICT), Trí tuệ nhân tạo (AI), và Vạn vật kết nối (IoT).","C. Học vấn số hoá (DL), Trí tuệ nhân tạo (AI), và Khoa học giáo dục STEM.","D. Khoa học máy tính (CS), Vạn vật kết nối (IoT), và Công nghệ thông tin và truyền thông (ICT)."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":72,"question":"Câu 2: (NB) Ở cấp trung học phổ thông, môn Tin học được phân hóa theo định hướng nghề nghiệp. Phương án nào sau đây nêu đúng hai định hướng của môn học?","options":["A. Tin học ứng dụng và Khoa học máy tính.","B. Tin học ứng dụng và Học vấn số hóa.","C. Khoa học máy tính và Học vấn số hóa.","D. Khoa học máy tính và Công nghệ thông tin."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":73,"question":"Câu 3: (NB) Theo Chương trình GDPT 2018 môn Tin học, việc xây dựng các yêu cầu cần đạt về phẩm chất và năng lực không dựa trên căn cứ trực tiếp nào sau đây?","options":["A. Chuẩn đầu ra mô tả trong các tài liệu giáo dục quốc tế của những tổ chức uy tín như UNESCO và OECD.","B. Kết quả khảo sát mức độ đạt được về kiến thức và kỹ năng của học sinh theo chương trình môn học trước đây.","C. Quy định chỉ tiêu tuyển chọn sinh viên đầu vào của các trường đại học đào tạo chuyên ngành công nghệ thông tin.","D. Dự báo nhu cầu phát triển năng lực tin học của người học phục vụ cho Cách mạng công nghiệp lần thứ tư."],"correctIndex":2,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":74,"question":"Câu 4: (TH) Việc khai thác các nguồn tài nguyên học tập trên môi trường số để mở rộng kiến thức ngoài nội dung trên lớp giúp học sinh hình thành năng lực thành phần nào sau đây?","options":["A. Năng lực sử dụng và quản lí các phương tiện công nghệ thông tin và truyền thông (NLa).","B. Năng lực ứng xử phù hợp trong môi trường số (NLb).","C. Năng lực ứng dụng công nghệ thông tin và truyền thông trong học và tự học (NLd).","D. Năng lực hợp tác trong môi trường số (NLe)."],"correctIndex":2,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":75,"question":"Câu 5: (TH) Khi tìm hiểu về cấu trúc phân hóa của môn Tin học cấp THPT trong Chương trình GDPT 2018, nhận định nào sau đây diễn giải đúng về sự khác biệt giữa hai định hướng?","options":["A. Định hướng Khoa học máy tính nghiên cứu nguyên lý hoạt động hệ thống, còn định hướng Tin học ứng dụng khai thác các công cụ phần mềm.","B. Định hướng Khoa học máy tính trang bị kỹ thuật sửa chữa phần cứng, còn định hướng Tin học ứng dụng đào tạo các kỹ năng văn phòng cơ bản.","C. Định hướng Khoa học máy tính dành cho học sinh chuyên toán tự nhiên, còn định hướng Tin học ứng dụng phù hợp với học sinh khối xã hội.","D. Định hướng Khoa học máy tính yêu cầu tạo ra sản phẩm thương mại, còn định hướng Tin học ứng dụng phục vụ mục đích kiểm tra lý thuyết."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":76,"question":"Câu 6: (TH) Khi xây dựng nội dung dạy học môn Tin học, giáo viên cần xác định mối quan hệ giữa các chủ đề và ba mạch kiến thức. Phương án nào sau đây mô tả đúng mối quan hệ đó?","options":["A. Mỗi chủ đề dành tỉ lệ tương đương cho các mạch kiến thức được triển khai.","B. Từng chủ đề thường có hai mạch chính; mạch thứ ba tùy theo cấp học.","C. Nội dung các mạch được phân bổ thành những nhóm chủ đề tương ứng ở mỗi cấp học.","D. Mức đóng góp của từng mạch thay đổi theo nội dung cụ thể của chủ đề."],"correctIndex":3,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":77,"question":"Câu 7: (TH) Trong buổi sinh hoạt chuyên môn, các giáo viên trao đổi về cách tổ chức nội dung môn Tin học thành các mạch kiến thức. Phương án nào sau đây nêu đúng mục đích của cách tổ chức này?","options":["A. Giúp học sinh ghi nhớ các khái niệm và thuật ngữ Tin học cơ bản.","B. Giúp học sinh gắn kiến thức với năng lực Tin học cần hình thành.","C. Giúp giáo viên sắp xếp nội dung bài học theo trình tự thống nhất.","D. Giúp nhà trường phân bổ nội dung kiểm tra theo từng giai đoạn."],"correctIndex":1,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":78,"question":"Câu 8: (VD) Một thư viện nhỏ có quầy mượn và phòng đọc. Máy tính ở hai khu vực cần dùng chung Internet và một máy in. Giáo viên muốn đánh giá yêu cầu “Trình bày và giải thích sơ lược được việc thiết kế mạng LAN cho một tổ chức nhỏ”. Phương án nào sau đây là nhiệm vụ phù hợp cho học sinh?","options":["A. Phác thảo mạng hai khu vực, giải thích cách dùng chung Internet và máy in.","B. Chọn thiết bị cho hai khu vực, giải thích chức năng và dự kiến số lượng cần dùng.","C. Vẽ tuyến dây giữa hai khu vực, giải thích vị trí lắp đặt và số cổng kết nối.","D. Nêu trình tự lắp mạng hai khu vực, giải thích cách kiểm tra tốc độ truy cập."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":79,"question":"Câu 9: (VD) Trong buổi sinh hoạt chuyên môn nhằm thiết kế dự án học tập STEM có ứng dụng Tin học cho học sinh THCS, các giáo viên đưa ra nhiều quan điểm sư phạm khác nhau. Căn cứ vào định hướng nội dung và yêu cầu cần đạt của Chương trình GDPT 2018, phương án nào sau đây là quyết định sư phạm phù hợp?","options":["A. Hướng dẫn học sinh vận dụng tổng hợp các kiến thức liên môn để tạo ra những sản phẩm số phục vụ thực tiễn  học tập và đời sống.","B. Giao bài tập yêu cầu học sinh sử dụng phần mềm đồ họa chỉnh sửa ảnh nghệ thuật đơn thuần để làm đẹp cho sản phẩm báo cáo cuối khóa.","C. Yêu cầu học sinh tích hợp trực tiếp các thư viện mã nguồn mở phức tạp vào dự án nhằm mục đích thương mại hóa sản phẩm ra thị trường.","D. Tập trung toàn bộ thời lượng vào việc luyện tập cú pháp thuật toán viết mã nguồn nâng cao để phục vụ cho các kỳ thi học sinh giỏi."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":80,"question":"Câu 10: (VD) Một giáo viên Tin học cấp THCS muốn thiết kế bài tập vận dụng cho học sinh, nhưng do phòng máy xảy ra sự cố kỹ thuật đột xuất, phần mềm dự kiến dùng cho cả lớp không thể khởi động được. Để giải quyết tình huống phát sinh này mà vẫn đảm bảo mục tiêu chất lượng, phương án nào sau đây là cách xử lí phù hợp với tình huống?","options":["A. Thay đổi phương pháp và nội dung tiếp cận, dựa trên hệ thống chuẩn biểu hiện năng lực.","B. Chuyển sang hệ thống bài tập lí thuyết về quy trình vận hành, lấy tài liệu sách giáo khoa làm thước đo.","C. Chia nhỏ bài học thành các nhiệm vụ ghi chép độc lập, lấy từng thành phần năng lực làm thước đo.","D. Phân tách lớp học theo định hướng chuyên sâu khoa học, lấy thế mạnh nghề nghiệp làm thước đo."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":81,"question":"Câu 1: (NB) Khi đánh giá kết quả học tập môn Tin học, phương án nào sau đây nêu đúng nội dung được đánh giá chủ yếu?","options":["A. Năm phẩm chất chủ yếu, ba năng lực chung và kết quả qua từng học kỳ.","B. Kiến thức ghi nhớ, thao tác phần mềm và mức hoàn tất bài thực hành.","C. Năm thành phần năng lực Tin học, đối chiếu với yêu cầu cần đạt.","D. Sản phẩm số, thái độ học tập và điểm kiểm tra qua từng chủ đề."],"correctIndex":2,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":82,"question":"Câu 2: (NB) Theo Chương trình GDPT 2018 môn Tin học, quy định định mức tối thiểu về số học sinh sử dụng chung một máy tính trong giờ thực hành ở cấp Trung học cơ sở là phương án nào dưới đây?","options":["A. 1","B. 2","C. 3","D. 4"],"correctIndex":1,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":83,"question":"Câu 3: (NB) Khi tiến hành xây dựng phân phối chương trình môn Tin học, tổ chuyên môn cần căn cứ vào thông số nào sau đây để tính toán và chia số tiết cụ thể cho các mạch nội dung chính?","options":["A. Tỉ lệ thời lượng quy định cho từng mạch nội dung trong chương trình tổng thể.","B. Khả năng tiếp thu thực tế của từng lớp học được đánh giá từ năm học trước.","C. Số lượng thiết bị phần cứng hiện có tại phòng thực hành của nhà trường.","D. Cấu trúc và trình tự bài học được biên soạn trong cuốn sách giáo khoa được chọn."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":84,"question":"Câu 4: (TH) Đối với quá trình đánh giá kết quả giáo dục môn Tin học, việc giáo viên lập hồ sơ học tập dưới dạng cơ sở dữ liệu đơn giản có ý nghĩa chủ yếu nào sau đây?","options":["A. Lưu trữ, cập nhật kết quả đánh giá thường xuyên nhằm xác định hiện tại năng lực tin học của học sinh ở đâu trên trục phát triển năng lực.","B. Tự động hóa hoàn toàn quy trình chấm điểm và đánh giá trên hệ thống nhằm thay thế những bài kiểm tra định kỳ bắt buộc trên lớp.","C. Tự động số hóa hồ sơ học tập nhằm hạn chế tối đa việc giáo viên phải trực tiếp theo dõi, ghi chép quá trình thao tác ở trên máy tính.","D. Thiết lập hệ thống xếp hạng thành tích công khai với mục đích thúc đẩy sự cạnh tranh điểm số giữa các học sinh trong toàn bộ khóa học."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":85,"question":"Câu 5: (TH) Một nhóm học sinh tìm cách giúp các bạn trong trường nhớ lịch trả sách thư viện. Các em tạo bảng nhắc hạn điện tử, nhờ một nhóm bạn dùng thử rồi chỉnh sửa theo phản hồi. Cách tổ chức dạy học nào sau đây được thể hiện rõ nhất qua hoạt động này?","options":["A. Liên hệ thực tiễn, tạo sản phẩm số và kiểm chứng hiệu quả của giải pháp.","B. Tăng thời lượng thực hành, tạo cơ hội thao tác và luyện sử dụng phần mềm.","C. Phát huy hợp tác, phân chia vai trò và tự quản lý tiến độ trong nhóm.","D. Đánh giá kết quả dựa trên hình thức, chức năng và mức hoàn thiện của sản phẩm."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":86,"question":"Câu 6: (TH) Trong giờ học giải quyết vấn đề với sự trợ giúp của máy tính, một nhóm đề xuất nhiều cách giải và dùng sơ đồ để thể hiện mối liên hệ giữa các bước. Nội dung đánh giá nào sau đây phù hợp với trọng tâm của mạch Khoa học máy tính (CS)?","options":["A. Sáng tạo và tư duy hệ thống khi học sinh đề xuất cách giải.","B. Ứng xử phù hợp trong tình huống số theo các quy tắc đã học.","C. Vận dụng kĩ năng tạo sản phẩm số và mức độ hoàn thiện.","D. Tiến bộ cá nhân so với yêu cầu cần đạt của giai đoạn học tập."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":87,"question":"Câu 7: (TH) Chương trình môn Tin học 2018 định hướng nội dung dạy học không phụ thuộc vào thiết bị phần cứng hay phần mềm cụ thể. Theo đó, yêu cầu bắt buộc đối với hoạt động kiểm tra đánh giá là phương án nào dưới đây?","options":["A. Tập trung đo lường năng lực giải quyết vấn đề và vận dụng kiến thức tạo ra sản phẩm.","B. Ưu tiên kiểm tra hệ thống lý thuyết nền tảng để giảm bớt áp lực thực hành trên máy tính.","C. Hướng tới việc xây dựng nhiều phiên bản đề thi khác nhau tương ứng với từng công cụ phần mềm.","D. Dựa trên việc sử dụng các phần mềm giả lập để tạo sự thống nhất cho mọi điều kiện cơ sở vật chất."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":88,"question":"Câu 8: (VD) Khi dạy chủ đề E “Ứng dụng tin học”, giáo viên muốn phát huy khả năng tự học, hợp tác và tính chủ động của học sinh. Cách tiếp cận nào dưới đây phù hợp với phương pháp dạy học tích cực?","options":["A. Học sinh xác định nhu cầu thực tế, đề xuất giải pháp, tạo sản phẩm số và kiểm chứng hiệu quả sử dụng.","B. Giáo viên nêu vấn đề thực tiễn, minh họa thao tác phần mềm rồi hướng dẫn học sinh thực hành tạo sản phẩm số theo mẫu.","C. Các nhóm phân tích sản phẩm số có sẵn, thảo luận ưu nhược điểm và lựa chọn giải pháp phù hợp với yêu cầu thực tế.","D. Với nhiệm vụ chung đã xác định, từng thành viên phân công công việc, phối hợp thực hiện sản phẩm số theo nhiệm vụ và tiêu chí đánh giá do giáo viên xác định."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":89,"question":"Câu 9: (VD) Với bài học Tin học thiên về lí thuyết, thời lượng trên lớp không đủ để thực hành ngay. Phương pháp nào sau đây phù hợp để tổ chức “Hoạt động 4: Vận dụng”?","options":["A. Giao yêu cầu vận dụng của một cụm bài học dưới dạng dự án nhỏ để học sinh thực hiện tại nhà.","B. Lồng ghép yêu cầu vận dụng vào phần kiểm tra kiến thức đầu giờ của tiết học tiếp theo để tiết kiệm thời gian.","C. Chuyển đổi mục tiêu vận dụng thành các bài tập trắc nghiệm lý thuyết để học sinh hoàn thành nhanh trên giấy.","D. Thiết kế một môi trường giả định bằng lời nói để học sinh thảo luận nhóm thay cho việc thao tác trên máy."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":90,"question":"Câu 10: (VD) Ban tổ chức hội chợ sách dùng bảng tính do một học sinh thiết kế để theo dõi thu, chi. Khi chạy thử, một khoản chi bị nhập nhầm rồi sửa; số dư cuối ngày vẫn trông hợp lý nhưng chưa được kiểm chứng. Giáo viên muốn biết bảng có xử lý đúng khi dữ liệu thay đổi hay không. Phương án nào sau đây giúp đánh giá phù hợp?","options":["A. Rà nhãn cột, định dạng tiền và vùng nhập, bảo đảm người dùng phân biệt khoản thu, khoản chi và ngày ghi nhận.","B. Yêu cầu học sinh giải thích công thức, chỉ vùng nhập và nêu cách cập nhật khi một giao dịch được điều chỉnh.","C. Nhập bộ giao dịch thử, sửa một khoản chi, đối chiếu tổng thu và số dư sau sửa với phép tính độc lập.","D. Đối chiếu bảng với mẫu giáo viên bằng bộ dữ liệu ban đầu, kiểm tra các trường nhập và tổng cuối ngày."],"correctIndex":2,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":91,"question":"Câu 1: (NB) Phương án nào sau đây là phù hợp trong khâu quản lý kế hoạch giáo dục nhà trường?","options":["A. Khảo sát nhu cầu, phân công nhiệm vụ, tổng kết hoạt động và xếp loại cuối năm.","B. Xác định nội dung, chuẩn bị thiết bị, tổ chức giảng dạy và kiểm tra học sinh.","C. Xây dựng kế hoạch, tổ chức thực hiện, kiểm tra giám sát, điều chỉnh hoàn thiện.","D. Thống nhất mục tiêu, triển khai chuyên đề, sơ kết học kỳ và báo cáo kết quả."],"correctIndex":2,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":92,"question":"Câu 2: (NB) Ở cấp THPT, văn bản nào sau đây của Bộ GD&ĐT cung cấp các hướng dẫn và phụ lục mẫu chi tiết cho việc xây dựng kế hoạch giáo dục của nhà trường theo Chương trình Giáo dục phổ thông (GDPT) 2018?","options":["A. Công văn 5512/BGDDT-GDTrH ngày 18/12/2020.","B. Công văn 4555/BGDDT-GDTrH ngày 18/12/2020.","C. Công văn 3280/BGDDT-GDTrH ngày 18/12/2020.","D. Công văn 2345/BGDDT-GDTrH ngày 18/12/2020."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":93,"question":"Câu 3: (NB) Khi xây dựng kế hoạch giáo dục, nhà trường cần căn cứ quy định của Bộ Giáo dục và Đào tạo về khung kế hoạch thời gian năm học. Phương án nào sau đây nêu đúng tổng số tuần triển khai giảng dạy trong một năm?","options":["A. 33.","B. 34.","C. 35.","D. 36."],"correctIndex":2,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":94,"question":"Câu 4: (TH) Phương án nào sau đây thể hiện đúng mối quan hệ giữa kế hoạch giáo dục nhà trường và kế hoạch của giáo viên?","options":["A. Kế hoạch giáo viên quyết định mục tiêu chung và nội dung của nhà trường.","B. Kế hoạch cấp trường định hướng kế hoạch dạy học, giáo dục của giáo viên.","C. Hai kế hoạch được xây dựng độc lập theo mục tiêu riêng của từng cấp học.","D. Kế hoạch cấp trường tổng hợp các bài dạy của giáo viên sau khi năm học kết thúc."],"correctIndex":1,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":95,"question":"Câu 5: (TH) Một trường THPT tự xây dựng và hoàn thiện kế hoạch giáo dục, sau đó mời phụ huynh và các tổ chức địa phương hỗ trợ triển khai. Phương án nào sau đây nhận xét phù hợp về việc phát huy xã hội hóa giáo dục trong cách làm này?","options":["A. Kết nối nhà trường, gia đình và cộng đồng trong xây dựng, thực hiện hoạt động giáo dục.","B. Huy động nguồn lực địa phương, các nhà hảo tâm để bổ sung thiết bị, phòng học và phương tiện dạy học.","C. Mời gia đình hỗ trợ học sinh thực hiện nhiệm vụ học tập ngoài giờ lên lớp.","D. Phối hợp với tổ chức địa phương để triển khai hoạt động ngoại khóa cho học sinh."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":96,"question":"Câu 6: (TH) Khi tổ chuyên môn Tin học thực hiện xây dựng KHDH theo định hướng phát triển năng lực, nhận định nào sau đây nêu đúng vị trí của sách giáo khoa so với chương trình môn học?","options":["A. Có sự phối hợp khi triển khai, song còn hạn chế cơ hội tham gia góp ý trong quá trình xây dựng kế hoạch.","B. Bảo đảm sự tham gia xuyên suốt, bởi hỗ trợ thực hiện đã thể hiện vai trò đóng góp vào việc hình thành kế hoạch.","C. Phát huy quyền chủ động của các bên, vì tách biệt khâu xây dựng và triển khai giúp phân định trách nhiệm giáo dục.","D. Tạo điều kiện để gia đình và cộng đồng xác định mục tiêu giáo dục, dựa trên các hoạt động đã được nhà trường lựa chọn.."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":97,"question":"Câu 7: (TH) Khi thiết lập phân phối chương trình môn Tin học, nguyên tắc nào sau đây cần được ưu tiên tuân thủ khi xác định thời điểm giảng dạy cho các cụm chuyên đề lựa chọn?","options":["A. Tránh bố trí lịch dạy chuyên đề trùng với các tuần đã ấn định cho kiểm tra, đánh giá định kỳ.","B. Bố trí dồn thời lượng chuyên đề vào cuối học kì II để học sinh có đủ thời gian hoàn thiện các dự án thực hành.","C. Tích hợp nội dung chuyên đề vào các tiết học cốt lõi có chủ đề tương đồng để tối ưu hóa quỹ thời gian bộ môn.","D. Thiết kế lịch học chuyên đề linh hoạt vào các tuần dự phòng để không làm gián đoạn mạch kiến thức của môn học chính khóa."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":98,"question":"Câu 8: (VD) Tại một trường THPT, khối 12 có 10 lớp nhưng chỉ có một phòng máy tính gồm 30 máy hoạt động tốt và hai giáo viên Tin học. Để đảm bảo thực hiện môn Tin học lựa chọn đúng theo hướng dẫn xây dựng kế hoạch giáo dục nhà trường, giải pháp phân phối thời gian nào sau đây là phù hợp?","options":["A. Tổ chức cho toàn bộ các lớp học dồn vào học kỳ một để giải phóng thời gian cho giáo viên bồi dưỡng chuyên môn vào học kỳ hai.","B. Bố trí một số lớp học ở học kỳ một và các lớp còn lại học ở học kỳ hai nhằm tối ưu hóa công suất phòng máy tính.","C. Yêu cầu toàn bộ học sinh tự thực hành tại nhà và chỉ bố trí các tiết lý thuyết trên lớp để tránh quá tải cho phòng máy.","D. Chia đều hai tiết mỗi tuần cho tất cả các lớp trong suốt ba mươi lăm tuần thực học nhằm đảm bảo tiến độ đồng bộ cả trường."],"correctIndex":1,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":99,"question":"Câu 9: (VD) Trong buổi sinh hoạt chuyên môn theo nghiên cứu bài học để hoàn thiện kế hoạch dạy học chủ đề thuật toán môn Tin học, tổ chuyên môn tiến hành dự giờ tiết dạy của một giáo viên. Sau khi quan sát, giáo viên nhận thấy nhiều học sinh còn lúng túng và chưa vẽ được sơ đồ khối giải quyết bài toán. Trong quy trình phân tích hoạt động học để xây dựng kế hoạch giáo dục nhà trường, tổ chuyên môn cần thực hiện bước xử lý sư phạm nào sau đây?","options":["A. Phân tích nguyên nhân dẫn đến khó khăn để kịp thời đề xuất biện pháp khắc phục và hoàn thiện kế hoạch bài dạy.","B. Tiến hành bỏ phiếu xếp loại tiết dạy của giáo viên để làm căn cứ đánh giá thi đua chuyên môn cuối năm.","C. Yêu cầu giáo viên thay thế nội dung vẽ sơ đồ khối bằng bài tập lý thuyết trắc nghiệm trên máy tính nhằm tránh quá tải.","D. Giáo viên trực tiếp thao tác mẫu lại các bước vẽ sơ đồ trên bảng để toàn bộ học sinh trong lớp chép lại vào vở."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":100,"question":"Câu 10: (VD) Đầu năm học, tổ chuyên môn Tin học tại một trường THPT phân tích đặc điểm tình hình để lập kế hoạch giáo dục. Kết quả khảo sát cho thấy số lượng học sinh khối 10 tăng mạnh, trong khi hệ thống máy tính tại phòng thực hành đã xuống cấp và không cài đặt được các phần mềm học tập cần thiết. Trước thực tế này, phương án nào sau đây giúp tổ chuyên môn xây dựng kế hoạch khả thi cho mạch Tin học ứng dụng (ICT)?","options":["A. Khai thác các nền tảng đồ họa trực tuyến hoặc phần mềm mã nguồn mở có chức năng tương đương để tổ chức thực hành.","B. Chuyển đổi trọng tâm phân phối chương trình sang việc giảng dạy chuyên sâu mạch Khoa học máy tính (CS) để giảm phụ thuộc cấu hình.","C. Tăng cường trình chiếu video hướng dẫn các kĩ thuật đồ họa phức tạp và tổ chức cho học sinh thảo luận phân tích quy trình.","D. Chuyển các tiết thực hành thành hoạt động làm việc nhóm để phác thảo ý tưởng và thiết kế bố cục sản phẩm."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":101,"question":"Câu 1: (NB) Kế hoạch giáo dục của tổ chuyên môn bao gồm những kế hoạch nào sau đây?","options":["A. Phân công giáo viên và kiểm tra, đánh giá định kỳ.","B. Dạy học cá nhân và bài dạy của từng giáo viên.","C. Hoạt động của nhà trường và giáo dục địa phương.","D. Dạy học môn học và tổ chức các hoạt động giáo dục."],"correctIndex":3,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":102,"question":"Câu 2: (NB) Dựa trên sơ đồ quy trình xây dựng kế hoạch giáo dục của tổ chuyên môn, nhiệm vụ phân phối chương trình được thực hiện thuộc bước nào sau đây?","options":["A. 1: Phân tích đặc điểm tình hình.","B. 2: Xây dựng kế hoạch dạy học.","C. 3: Xây dựng kế hoạch tổ chức các hoạt động giáo dục.","D. 4: Rà soát, hoàn thiện kế hoạch giáo dục của tổ chuyên môn."],"correctIndex":1,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":103,"question":"Câu 3: (NB) Theo cấu trúc khung kế hoạch tổ chức các hoạt động giáo dục của tổ chuyên môn, ngoài các cột về :“Chủ đề, Yêu cầu cần đạt, Số tiết, Thời điểm và Địa điểm”. Khung kế hoạch còn quy định những thông tin nào sau đây?","options":["A. Phương pháp giảng dạy, ghi chú và thang điểm đánh giá thường xuyên.","B. Tiến trình hoạt động trên lớp, nhiệm vụ của học sinh và sản phẩm học tập.","C. Đơn vị chủ trì, lực lượng phối hợp và các điều kiện thực hiện hoạt động.","D. Phạm vi và nội dung sử dụng, cấu hình máy tính yêu cầu, công cụ kiểm tra."],"correctIndex":2,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":104,"question":"Câu 4: (TH) Sự tham gia của các thành viên tổ chuyên môn trong quá trình xây dựng kế hoạch có ý nghĩa nào sau đây?","options":["A. Bảo đảm việc xây dựng kế hoạch có tính thống nhất và sự đồng thuận về mục tiêu chung.","B. Giúp san sẻ trách nhiệm chính của tổ trưởng chuyên môn cho tất cả các thành viên trong tổ.","C. Tạo cơ sở để mỗi giáo viên thiết kế một bản phân phối chương trình của riêng mình.","D. Hỗ trợ giáo viên cá nhân hóa các nhiệm vụ ngay trong quá trình cùng xây dựng kế hoạch chung."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":105,"question":"Câu 5: (TH) Khi xây dựng kế hoạch giáo dục của tổ chuyên môn, yêu cầu bảo đảm \"tính pháp lý\" được thể hiện thông qua định hướng nào sau đây?","options":["A. Dựa trên năng lực chuyên môn và nguyện vọng đăng ký lịch làm việc của các giáo viên.","B. Theo mỗi nhu cầu học tập thực tế và các sở thích cá nhân của từng nhóm học sinh trong lớp.","C. Căn cứ vào văn bản hướng dẫn nhiệm vụ năm học và khung kế hoạch chương  của trường.","D. Bám sát danh mục các thiết bị thực hành và hệ thống phòng máy tính thực tế của nhà trường."],"correctIndex":2,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":106,"question":"Câu 6: (TH) Để bảo đảm tính khả thi, kế hoạch giáo dục của tổ chuyên môn cần được xây dựng dựa vào nguyên tắc nào sau đây?","options":["A. Dựa vào khung kế hoạch thời gian năm học do UBND tỉnh ban hành.","B. Căn cứ vào đặc điểm học sinh, đội ngũ và điều kiện cơ sở vật chất.","C. Bảo đảm sự thống nhất về tiến độ và nội dung giữa các môn học.","D. Cho phép điều chỉnh nội dung khi có thay đổi về thực tiễn giảng dạy."],"correctIndex":1,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":107,"question":"Câu 7: (TH) Việc xây dựng kế hoạch giáo dục của tổ chuyên môn mang lại ý nghĩa như thế nào đối với công tác quản lý của nhà trường?","options":["A. Là cơ sở để các tổ chuyên môn phối hợp thực hiện các quy định quản lý chuyên môn.","B. Giúp bảo đảm tính thống nhất và là căn cứ theo dõi, đánh giá thực hiện kế hoạch giáo dục.","C. Tạo tiền đề để giáo viên điều chỉnh nội dung, phương pháp dạy học phù hợp với điều kiện và nhu cầu học sinh.","D. Phục vụ cho công tác phân bổ thời lượng và sắp xếp lịch dạy cho giáo viên trong tổ."],"correctIndex":1,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":108,"question":"Câu 8: (VD) Trong quá trình thực hiện kế hoạch giáo dục, tổ Tin học đối mặt với ba thay đổi đột ngột: Thời lượng học kỳ II bị rút ngắn; Phải bổ sung một chuyên đề mới theo chỉ đạo của Sở GD&ĐT; Học sinh khối 12 cần ưu tiên tối đa cho việc ôn tập thi tốt nghiệp. Tổ chuyên môn cần vận dụng các nguyên tắc xây dựng kế hoạch nào sau đây để đưa ra giải pháp điều chỉnh tối ưu?","options":["A. Ưu tiên cắt bỏ một số nội dung không cần thiết trong chương trình để có đủ thời lượng dạy chuyên đề của Sở, thời gian còn lại dồn để ôn thi.","B. Đảm bảo quyền lợi khối 12: giữ nguyên kế hoạch khối 10, 11 nhưng dạy với nhịp độ nhanh hơn, dùng thời gian để tăng cường ôn tập cho khối 12.","C. Tinh giản các nội dung không cốt lõi, tích hợp các bài học tương đồng, bố trí chuyên đề mới và dành thời gian ôn tập trọng tâm cho khối 12.","D. Áp dụng giải pháp công bằng: giảm đều một phần thời lượng của tất cả các chủ đề hiện có để chia sẻ cho chuyên đề mới và thời gian ôn tập."],"correctIndex":2,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":109,"question":"Câu 9: (VD) Khi xây dựng phân phối chương trình môn Tin học, tổ chuyên môn nhận thấy học sinh của trường cần thêm thời gian để tiếp cận các khái niệm nền tảng trong mạch Lập trình so với thời lượng gợi ý trong sách giáo khoa tỉnh lựa chọn. Phương án nào sau đây thể hiện cách phân bổ thời lượng phù hợp với đặc điểm học sinh?","options":["A. Đề xuất với Hiệu trưởng xin tăng thêm tổng thời lượng môn học nhằm mục đích có đủ quỹ thời gian ôn tập nền tảng trước khi dạy bài mới.","B. Phân bổ đồng đều quỹ thời gian quy định cho các mạch nội dung nhằm đảm bảo học sinh có cơ hội tiếp cận đầy đủ các kiến thức từ cơ bản đến nâng cao.","C. Thiết kế lại cấu trúc bài học thành chủ đề mới, căn cứ vào mức độ phức tạp của các yêu cầu cần đạt để tăng thêm thời lượng phân bổ sao cho phù hợp.","D. Tính toán số tiết dựa trên tỷ lệ phần trăm thời lượng quy định, sau đó giáo viên bộ môn sắp xếp lại thứ tự bài học sao cho phù hợp với trình độ từng lớp."],"correctIndex":2,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":110,"question":"Câu 10: (VD) Trong tiết thực hành \"Kết nối PC với các thiết bị số thông dụng\" ở lớp 12, nhà trường chưa trang bị các thiết bị số mới. Giải pháp tổ chức dạy học nào dưới đây vừa đảm bảo tiến độ vừa đáp ứng đúng yêu cầu cần đạt?","options":["A. Tổ chức cho học sinh quan sát cổng cắm trên vỏ máy tính và vẽ sơ đồ nguyên lý ghép nối ra giấy để ghi nhớ thao tác.","B. Dùng thiết bị cũ, hỏng để thao tác cắm cáp vật lí và dùng video, hình ảnh để mô phỏng phần kết nối logic.","C. Tập trung hướng dẫn học sinh thao tác cài đặt các trình điều khiển (driver) trên hệ điều hành để thay thế cho quá trình ghép nối phần cứng.","D. Khuyến khích học sinh mang thiết bị thông minh từ gia đình đến phòng máy để các nhóm có đầy đủ công cụ thực hành cấu hình mạng."],"correctIndex":1,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":111,"question":"Câu 1 (NB): Căn cứ vào các tiêu chí trong Công văn số 5555/BGDĐT-GDTrH và đặc điểm của Chương trình giáo dục phổ thông 2018, phương án nào sau đây nêu đúng số lượng yêu cầu cần đáp ứng khi xây dựng kế hoạch bài dạy (KHBD) cho một chủ đề?","options":["A. 4.","B. 5.","C. 6.","D. 7."],"correctIndex":2,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":112,"question":"Câu 2: (NB) Phương án nào sau đây xác định đúng các thành phần cơ bản của một hoạt động học trong kế hoạch bài dạy theo định hướng tại Công văn 5512/BGDĐT-GDTrH?","options":["A. Mục tiêu, nội dung, sản phẩm và tổ chức thực hiện hoạt động.","B. Yêu cầu cần đạt, phân phối chương trình, kiểm tra và tổng kết.","C. Kiến thức trọng tâm, tài liệu tham khảo, thời khóa biểu và điểm.","D. Nội dung bài học, phương pháp giảng dạy, phiếu điểm và xếp loại."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":113,"question":"Câu 3 (NB): Trong quy trình 4 bước xây dựng kế hoạch bài dạy môn Tin học, sau khi hoàn thành \"Bước 1: Xác định mục tiêu của bài dạy\", giáo viên thực hiện bước tiếp theo nào sau đây?","options":["A. Xác định chuỗi các hoạt động học và mục tiêu của từng hoạt động.","B. Xây dựng chi tiết kịch bản tổ chức cho các hoạt động dạy học cụ thể.","C. Lựa chọn danh mục thiết bị phòng máy và phần mềm thực hành tương ứng.","D. Rà soát và hoàn thiện tổng thể cấu trúc của bản kế hoạch bài dạy."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 1","level":"NB","levelName":"Nhận biết"},
{"id":114,"question":"Câu 4. (TH) Một mục tiêu trong dự thảo kế hoạch bài dạy được viết: “Giáo viên hướng dẫn học sinh sử dụng câu lệnh rẽ nhánh để giải quyết bài toán”. Phương án nào sau đây xác định nội dung cần điều chỉnh để mục tiêu thể hiện kết quả học tập mong đợi?","options":["A. Cụ thể hóa dạng bài toán để xác định phạm vi kiến thức được triển khai trong tiết học.","B. Bổ sung điều kiện thực hành để làm rõ thiết bị và học liệu hỗ trợ quá trình học tập.","C. Diễn đạt thành hành động học sinh thực hiện được sau khi hoàn thành bài học.","D. Xác định mức độ hướng dẫn để phân biệt nhiệm vụ của giáo viên và nhiệm vụ của học sinh."],"correctIndex":2,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":115,"question":"Câu 5. (TH) Hai giáo viên dạy cùng một bài học nhưng lựa chọn nhiệm vụ, học liệu và thời lượng cho từng hoạt động khác nhau. Phương án nào sau đây giải thích sự khác biệt này?","options":["A. Nội dung và trình tự của bộ sách đang sử dụng quyết định cách phân chia hoạt động và thời lượng.","B. Kinh nghiệm tổ chức lớp học quyết định mức yêu cầu cần đạt và cách lựa chọn nhiệm vụ tương ứng.","C. Sự đồng thuận của tổ chuyên môn là căn cứ xác nhận mức độ phù hợp của từng phương án tổ chức.","D. Yêu cầu cần đạt được cụ thể hóa qua cách tổ chức phù hợp với người học và điều kiện dạy học."],"correctIndex":3,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":116,"question":"Câu 6. (TH) Khi thiết kế bài học mới, giáo viên sử dụng một nhiệm vụ giúp học sinh huy động kiến thức từ bài trước để phát hiện vấn đề cần tìm hiểu. Cách thiết kế này tạo cơ sở cho quá trình học tập theo phương án nào sau đây?","options":["A. Kết nối hiểu biết sẵn có với vấn đề mới để hình thành kiến thức.","B. Đánh giá mức độ ghi nhớ bài cũ của học sinh trước khi chuyển sang nội dung mới.","C. Tổng hợp lại nội dung trọng tâm của bài trước để đảm bảo tính hệ thống cho chủ đề.","D. Ôn tập lại các quy trình thực hành cũ nhằm duy trì phản xạ kĩ năng."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":117,"question":"Câu 7 (TH): Khi phân tích yêu cầu về sự đa dạng trong hình thức, phương pháp và kỹ thuật dạy học, quan điểm nào sau đây phù hợp với định hướng xây dựng kế hoạch bài dạy?","options":["A. Kết hợp các phương pháp dạy học trong từng hoạt động, bảo đảm mỗi bài học có sự thay đổi về cách thức tổ chức.","B. Lựa chọn phương pháp dạy học phù hợp với nội dung từng hoạt động, đồng thời sử dụng cách tổ chức đã phát huy hiệu quả qua các bài học.","C. Sử dụng phương pháp hợp lí, tránh chỉ dùng một cách dạy ở nhiều hoạt động và kết hợp các phương pháp khi cần thiết.","D. Phối hợp các phương pháp dạy học trong bài học, lựa chọn hình thức tổ chức phù hợp với đặc điểm của từng hoạt động."],"correctIndex":2,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 1","level":"TH","levelName":"Thông hiểu"},
{"id":118,"question":"Câu 8 (VD): Trong kế hoạch bài dạy Bài 9: An toàn trên không gian mạng (thuộc Chủ đề 2: Mạng máy tính và Internet), giáo viên giao nhiệm vụ thiết kế Infographic hướng dẫn bảo vệ tài khoản cá nhân tại nhà. Kế hoạch đã quy định sản phẩm, thời hạn nộp và tiêu chí đánh giá, nhưng sau khi nhận bài, giáo viên chỉ ghi điểm rồi chuyển sang chủ đề mới. Cách điều chỉnh nào sau đây phù hợp?","options":["A. Gửi điểm kèm nhận xét riêng cho từng bài, sau đó sử dụng thời gian tiết học để triển khai nội dung tiếp theo.","B. Chọn một số sản phẩm để trình bày ở tiết sau, tổ chức nhận xét theo tiêu chí và tổng kết những điểm cần cải thiện.","C. Yêu cầu mỗi người tự đối chiếu sản phẩm với tiêu chí, chỉnh sửa tại nhà rồi nộp lại bản hoàn thiện cho giáo viên.","D. Trình chiếu một số sản phẩm tiêu biểu ở tiết sau, phân tích cách trình bày và ghi nhận mức độ tham gia của người học."],"correctIndex":1,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":119,"question":"Câu 9 (VD): Khi dạy bài \"Thuật toán sắp xếp\" (Định hướng Khoa học máy tính), phòng máy của trường bất ngờ mất điện. Để duy trì mục tiêu phát triển tư duy máy tính trong kế hoạch bài dạy, giáo viên nên điều chỉnh kế hoạch tổ chức hoạt động theo cách nào dưới đây?","options":["A. Sử dụng các bộ thẻ số bằng bìa cứng và tổ chức cho học sinh đóng vai mô phỏng lại các bước thuật toán.","B. Thực hiện vẽ sơ đồ thuật toán lên bảng đen và yêu cầu cả lớp chú ý lắng nghe để ghi chép lại các bước xử lý.","C. Cung cấp các trạng thái của dãy số sau mỗi lượt sắp xếp, yêu cầu học sinh ghép với các bước thuật toán tương ứng.","D. Phát phiếu học tập chứa các đoạn mã lệnh in sẵn và yêu cầu học sinh thảo luận nhóm để tìm ra lỗi sai cú pháp."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"id":120,"question":"Câu 10. (VD) Trong bài học viết chương trình tìm kiếm, giáo viên đặt mục tiêu phát triển năng lực giao tiếp và hợp tác, với biểu hiện học sinh biết phân công, phối hợp và trao đổi để hoàn thành nhiệm vụ. Dự thảo hiện đánh giá qua chương trình của nhóm và phần trình bày của đại diện. Phương án nào sau đây bổ sung minh chứng phù hợp với mục tiêu này?","options":["A. Yêu cầu từng em giải thích một đoạn mã, dựa vào mức độ tương thích để nhận xét khả năng phối hợp.","B. Quan sát quá trình làm việc nhóm kết hợp với nhật ký và đánh giá chéo giữa các thành viên.","C. Thu nhật kí số dòng lệnh từng em đã viết và dùng tỉ lệ đóng góp để nhận xét chất lượng hợp tác.","D. Ghi nhận thời gian hoàn thành, số lỗi của sản phẩm và dùng kết quả để nhận xét sự phối hợp."],"correctIndex":1,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 1","level":"VD","levelName":"Vận dụng"},
{"question":"Câu 1 (Nhận biết): Trong kế hoạch giáo dục của nhà trường THPT, nội dung nào sau đây thuộc nhóm mục tiêu giáo dục năm học?","options":["A. Phương án bố trí thiết bị phục vụ giảng dạy.","B. Lịch triển khai hoạt động của các tổ chuyên môn.","C. Chỉ tiêu về chất lượng giáo dục của các khối lớp.","D. Phân công nhiệm vụ quản lý của các bộ phận."],"correctIndex":2,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":121},
{"question":"Câu 2 (Nhận biết): Khi tổ chuyên môn xây dựng kế hoạch dạy học môn học, văn bản nào sau đây được sử dụng làm cơ sở trực tiếp về tiến độ thực hiện?","options":["A. Kế hoạch giáo dục cá nhân của từng giáo viên.","B. Khung thời gian thực hiện chương trình của trường.","C. Kế hoạch giáo dục của tổ chuyên môn năm học trước.","D. Lịch sinh hoạt chuyên môn của các tổ trong trường."],"correctIndex":1,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":122},
{"question":"Câu 3 (Nhận biết): Theo hướng dẫn xây dựng kế hoạch giáo dục nhà trường, trách nhiệm xây dựng kế hoạch cụ thể cho một hoạt động giáo dục thuộc về đơn vị nào sau đây?","options":["A. Đơn vị được giao chủ trì tổ chức hoạt động đó.","B. Ban giám hiệu trực tiếp soạn thảo và ban hành.","C. Tổ trưởng chuyên môn của khối lớp tham gia.","D. Đoàn thanh niên hoặc bộ phận quản lý học sinh."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":123},
{"question":"Câu 4 (Thông hiểu): Trong cùng năm học, hai trường THPT có quy mô học sinh và điều kiện dạy học khác nhau. Nhận định nào sau đây phản ánh cách xây dựng chỉ tiêu giáo dục phù hợp với thực tế?","options":["A. Kết hợp kết quả học tập và điều kiện dạy học khi xác định chỉ tiêu.","B. Ưu tiên kế thừa chỉ tiêu năm trước để duy trì mức phấn đấu.","C. Đối chiếu chỉ tiêu của trường khác để thống nhất mức phấn đấu.","D. Phân bổ chỉ tiêu theo số lớp để xác định mức phấn đấu từng khối."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":124},
{"question":"Câu 5 (Thông hiểu): Hai trường THPT có cách phân bố số tiết môn Tin học theo từng tuần khác nhau. Yêu cầu nào sau đây cần được bảo đảm khi triển khai hai kế hoạch này?","options":["A. Bảo đảm tỉ lệ thời lượng giữa các chủ đề giống nhau ở hai trường.","B. Bảo đảm số tiết của môn học được phân bổ đều giữa các tuần.","C. Bảo đảm tổng số tiết và yêu cầu cần đạt của môn học.","D. Bảo đảm thời điểm hoàn thành mỗi chủ đề trùng nhau giữa các trường."],"correctIndex":2,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":125},
{"question":"Câu 6 (Thông hiểu): Trong sinh hoạt chuyên môn theo nghiên cứu bài học, việc phân tích nguyên nhân học sinh gặp khó khăn dựa trên quan sát hoạt động học chủ yếu nhằm xác định yếu tố nào sau đây?","options":["A. Những điểm cần điều chỉnh trong thiết kế và tổ chức hoạt động học.","B. Những nội dung học sinh cần luyện tập trước đợt kiểm tra định kì.","C. Mức độ hoàn thành nhiệm vụ của các nhóm học sinh trong tiết học.","D. Thời lượng đã sử dụng cho từng hoạt động so với kế hoạch bài dạy."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":126},
{"question":"Câu 7 (Thông hiểu): Việc huy động sự tham gia và lấy ý kiến của cha mẹ học sinh cùng các tổ chức xã hội khi xây dựng kế hoạch giáo dục nhà trường mang lại ý nghĩa nào sau đây?","options":["A. Tạo sự đồng thuận và phối hợp trong thực hiện kế hoạch giáo dục.","B. Xác định nội dung ưu tiên dựa trên nguyện vọng của các nhóm phụ huynh.","C. Xây dựng kế hoạch học tập theo nguồn lực hỗ trợ của từng gia đình.","D. Thống nhất chỉ tiêu đánh giá thông qua ý kiến của các tổ chức tham gia."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":127},
{"question":"Câu 8 (Vận dụng): Do số lượng phòng máy tính còn hạn chế, nhà trường chưa thể bố trí lịch học thực hành môn Tin học cho tất cả các lớp trong cùng một thời điểm. Phương án xử lý nào sau đây phù hợp với hướng dẫn thực hiện chương trình?","options":["A. Bố trí một số lớp làm bài thực hành theo nhóm tại phòng học thông thường.","B. Tăng số học sinh sử dụng chung máy tính trong các tiết thực hành bị trùng lịch.","C. Điều chỉnh kế hoạch dạy học để các lớp luân phiên sử dụng phòng máy tính.","D. Chuyển một số bài thực hành thành hoạt động mô phỏng trên lớp học lý thuyết."],"correctIndex":2,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":128},
{"question":"Câu 9 (Vận dụng): Khi rà soát kế hoạch năm học, nhà trường phát hiện hai tổ chuyên môn đăng ký sử dụng hội trường cùng một buổi cho hai hoạt động giáo dục khác nhau. Phương án điều phối nào sau đây bảo đảm tính khả thi của kế hoạch?","options":["A. Ưu tiên hoạt động có kế hoạch được gửi trước khi tổng hợp chung.","B. Rà soát mục tiêu và tiến độ để điều chỉnh lịch tổ chức từng hoạt động.","C. Ưu tiên hoạt động có số lượng học sinh tham gia đông hơn dự kiến.","D. Ưu tiên hoạt động có nhiều khách mời ngoài trường tham gia tổ chức."],"correctIndex":1,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":129},
{"question":"Câu 10 (Vận dụng): Sau học kỳ I triển khai kế hoạch giáo dục, nhà trường ghi nhận nhiều học sinh chưa đạt yêu cầu ở một số nội dung dù tiến độ dạy học vẫn bảo đảm. Trước khi quyết định các biện pháp hỗ trợ, nhà trường cần thực hiện công việc nào sau đây?","options":["A. Đối chiếu kết quả theo nội dung để xác định điểm cần điều chỉnh.","B. Tăng số buổi hỗ trợ học tập cho các lớp có kết quả thấp.","C. Thống nhất đề kiểm tra bổ sung để đánh giá lại toàn khối lớp.","D. Phân bổ lại thời lượng ôn tập cho các nội dung cuối học kì."],"correctIndex":0,"category":"c2_p1","chapter":"c2","topic":"Chương 2: Phần 1 (Xây dựng kế hoạch giáo dục nhà trường)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":130},
{"question":"Câu 1 (Nhận biết): Môn Tin học ở cấp trung học cơ sở có vị trí như thế nào trong chương trình giáo dục phổ thông?","options":["A. Là môn học tự chọn.","B. Là môn học lựa chọn bình đẳng như Vật lí, Hóa học.","C. Là môn học bắt buộc.","D. Là môn học tích hợp với môn Công nghệ."],"correctIndex":2,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":131},
{"question":"Câu 2 (Nhận biết): Theo chương trình tổng thể, môn Tin học có sứ mạng giúp học sinh hình thành và phát triển năng lực tin học bao gồm bao nhiêu thành phần?","options":["A. 3.","B. 4.","C. 5.","D. 7."],"correctIndex":2,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":132},
{"question":"Câu 3 (Nhận biết): Mục tiêu của chương trình môn Tin học ở cấp tiểu học giúp học sinh bước đầu làm quen với điều gì?","options":["A. Cách phân tích và thiết kế các thuật toán ở mức chuyên sâu.","B. Thế giới công nghệ số và những công cụ số gần gũi.","C. Cách tổ chức dữ liệu và quản trị các hệ thống máy tính.","D. Cách tổ chức dữ liệu và quản trị các hệ thống máy tính."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":133},
{"question":"Câu 4 (Thông hiểu): Nhận định nào dưới đây giải thích đúng về mối quan hệ giữa phân môn Tin học và phân môn Công nghệ ở cấp tiểu học?","options":["A. Hai phân môn được tổ chức với thời lượng học tập hoàn toàn khác nhau.","B. Mỗi phân môn có mục tiêu, yêu cầu cần đạt và nội dung đặc thù.","C. Mỗi phân môn sử dụng một hệ thống phương pháp dạy học riêng biệt.","D. Hai phân môn hướng đến những nhóm học sinh có năng lực khác nhau."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":134},
{"question":"Câu 5 (Thông hiểu): Dựa vào mạch kiến thức của công nghệ số, điểm khác biệt cốt lõi giữa Khoa học máy tính và Tin học ứng dụng là gì?","options":["A. Khoa học máy tính nhấn mạnh sử dụng công cụ số, còn Tin học ứng dụng nhấn mạnh thiết kế thuật toán.","B. Khoa học máy tính hướng đến kiến thức lí thuyết, còn Tin học ứng dụng hướng đến kiến thức về pháp luật số.","C. Khoa học máy tính phát triển tư duy giải quyết vấn đề trên nền tảng số, còn Tin học ứng dụng chú trọng tạo sản phẩm phục vụ thực tiễn.","D. Khoa học máy tính tập trung vào phần cứng, còn Tin học ứng dụng tập trung vào các hệ thống mạng và truyền thông."],"correctIndex":2,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":135},
{"question":"Câu 6 (Thông hiểu): Chương trình môn Tin học xác định ba mạch kiến thức cốt lõi gồm Học vấn số hóa phổ thông (DL), Công nghệ thông tin và truyền thông (ICT), và Khoa học máy tính (CS). Cách hiểu nào phù hợp nhất về mối quan hệ giữa ba mạch kiến thức này?","options":["A. Ba mạch kiến thức được tổ chức theo các nội dung khác nhau và triển khai lần lượt trong chương trình.","B. Ba mạch kiến thức bổ sung cho nhau và được kết hợp trong quá trình hình thành năng lực tin học.","C. Mỗi mạch kiến thức gắn với một cấp học khác nhau trong chương trình phổ thông.","D. Một mạch kiến thức giữ vai trò chính, hai mạch còn lại hỗ trợ cho quá trình học tập."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":136},
{"question":"Câu 7 (Thông hiểu): Một nhóm xây dựng chương trình phát hiện một số nội dung Tin học đang lặp lại giữa các cấp học và một số phần quá thiên về lí thuyết. Theo quan điểm “Tính kế thừa và phát triển”, cách điều chỉnh nào phù hợp nhất?","options":["A. Cập nhật toàn bộ nội dung theo các phần mềm và công nghệ đang phổ biến.","B. Giảm thời lượng thực hành để dành thêm thời gian cho kiến thức nền tảng.","C. Sắp xếp lại nội dung để hạn chế trùng lặp và tránh thiên về lí thuyết.","D. Tách các nội dung khó thành chuyên đề riêng và tăng thời lượng tự học."],"correctIndex":2,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":137},
{"question":"Câu 8 (Vận dụng): Lan chuẩn bị đăng kí môn học ở lớp 10. Trong phương án ban đầu, Lan không chọn Tin học, Công nghệ hoặc Nghệ thuật vì cho rằng đã đủ số môn ở các nhóm khác. Để phương án phù hợp với quy định nêu trong chương trình tổng thể, Lan nên điều chỉnh như thế nào?","options":["A. Bổ sung cả Tin học, Công nghệ và Nghệ thuật vào phương án đã chọn.","B. Bổ sung ít nhất một môn trong ba môn Tin học, Công nghệ hoặc Nghệ thuật.","C. Giữ nguyên phương án vì số môn ở các nhóm khác đã đáp ứng yêu cầu.","D. Thay một môn ở nhóm khác bằng hai môn thuộc nhóm Tin học, Công nghệ, Nghệ thuật."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":138},
{"question":"Câu 9 (Vận dụng): Một trường THCS tổ chức bốn hoạt động sau. Hoạt động nào phù hợp nhất với trọng tâm thực hành giải quyết vấn đề ở cấp THCS?","options":["A. Phân tích các chứng minh toán học phức tạp liên quan đến thuật toán tối ưu.","B. Tìm hiểu cấu trúc bên trong của hệ điều hành và cơ chế quản lí tiến trình.","C. Khảo sát thói quen sử dụng thiết bị số của học sinh và viết báo cáo giấy.","D. Thiết kế một sản phẩm số và thử nghiệm điều khiển một hệ thống tự động đơn giản."],"correctIndex":3,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":139},
{"question":"Câu 10 (Vận dụng): Giáo viên giao cho học sinh lớp 8 xây dựng một sản phẩm số tuyên truyền về an toàn giao thông. Hoạt động nào phù hợp nhất với mục tiêu môn Tin học cấp THCS?","options":["A. Đọc tài liệu, ghi lại nội dung chính và nộp bản tóm tắt.","B. Thu thập tư liệu, tạo sản phẩm số, biên tập và chia sẻ trên môi trường số.","C. Học các khái niệm về hệ thống máy tính và làm bài kiểm tra lí thuyết.","D. Phân tích một thuật toán có sẵn và mô tả lại các bước xử lí."],"correctIndex":1,"category":"c1_p12","chapter":"c1","topic":"Chương 1: Phần 1, 2 (Đặc điểm môn học & Mục tiêu chương trình)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":140},
{"question":"Câu 1 (Nhận biết): Trong Chương trình tổng thể, khi đề cập đến việc bồi dưỡng phẩm chất cho học sinh thông qua môn Tin học, yếu tố KHÔNG nằm trong nhóm 5 phẩm chất chủ yếu là:","options":["A. Yêu nước.","B. Trung thực.","C. Tự lực.","D. Trách nhiệm."],"correctIndex":2,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":141},
{"question":"Câu 2 (Nhận biết): Để tạo lập nền tảng kiến thức cho học sinh, cấu trúc nội dung dạy học hình thành sự hòa quyện từ ba mạch tri thức cốt lõi là:","options":["A. Kiến trúc hệ thống máy tính, an toàn thông tin mạng lưới, kĩ thuật lập trình số.","B. Khoa học dữ liệu ứng dụng, hệ thống điều khiển tự động, kĩ thuật thiết kế mạng.","C. Học vấn số hóa phổ thông, công nghệ thông tin và truyền thông, khoa học máy tính.","D. Tư duy giải quyết vấn đề, năng lực tự chủ tự học, kĩ năng giao tiếp và hợp tác."],"correctIndex":2,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":142},
{"question":"Câu 3 (Nhận biết): Trong chương trình giáo dục phổ thông môn Tin học 2018, phương án nào sau đây mô tả đúng số lượng chủ đề nội dung được thiết kế xuyên suốt cả ba cấp học?","options":["A. 5.","B. 6.","C. 7.","D. 9."],"correctIndex":2,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":143},
{"question":"Câu 4 (Thông hiểu): Nhận định nào sau đây phản ánh đúng bản chất của yêu cầu “đọc hiểu chương trình máy tính” trong việc bồi dưỡng năng lực, phẩm chất cho học sinh?","options":["A. Cho phép học sinh thay thế hoàn toàn các phần mềm ứng dụng thông thường bằng mã lệnh.","B. Giúp học sinh khai thác kinh nghiệm của người khác và tạo khả năng tiếp thu công nghệ.","C. Đảm bảo học sinh trở thành lập trình viên độc lập ngay sau khi hoàn thành cấp tiểu học.","D. Định hướng học sinh tập trung hoàn toàn vào việc giảng dạy ngôn ngữ lập trình cho bạn bè."],"correctIndex":1,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":144},
{"question":"Câu 5 (Thông hiểu): Trong Chương trình GDPT 2018 môn Tin học, nhận định nào sau đây mô tả đúng nhất mối quan hệ giữa “Yêu cầu cần đạt” và “Nội dung giáo dục”?","options":["A. Yêu cầu cần đạt và nội dung giáo dục có mối quan hệ biện chứng, tác động tương hỗ chặt chẽ với nhau.","B. Nội dung giáo dục là mục tiêu cốt lõi, còn yêu cầu cần đạt chỉ đóng vai trò tham khảo khi thiết kế bài dạy.","C. Yêu cầu cần đạt được xây dựng độc lập và không phụ thuộc vào các mạch kiến thức cốt lõi của môn học.","D. Nội dung giáo dục quy định chi tiết thời lượng bài học, không cho phép giáo viên linh hoạt điều chỉnh."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":145},
{"question":"Câu 6 (Thông hiểu): Theo tài liệu Nội dung giáo dục, tính “mở” trong việc tổ chức nội dung giáo dục cốt lõi môn Tin học 2018 được thể hiện qua quy định nào sau đây?","options":["A. Cho phép cơ sở giáo dục tự chọn mạch kiến thức trọng tâm thay cho Bộ Giáo dục.","B. Nội dung không phụ thuộc vào thiết bị phần cứng, phần mềm hay học liệu cụ thể.","C. Quy định cứng thời lượng của từng bài học để đảm bảo tính đồng bộ trên toàn quốc.","D. Bắt buộc nhà trường phải sử dụng phần mềm mã nguồn mở để giảng dạy thực hành."],"correctIndex":1,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":146},
{"question":"Câu 7 (Thông hiểu): Trong Chương trình GDPT 2018, môn Tin học đóng góp trực tiếp vào việc phát triển năng lực chung “Giải quyết vấn đề và sáng tạo” thông qua thành phần năng lực tin học nào?","options":["A. NLc: Giải quyết vấn đề với sự hỗ trợ của công nghệ thông tin và truyền thông.","B. NLd: Ứng dụng công nghệ thông tin và truyền thông trong học và tự học.","C. NLe: Hợp tác hiệu quả và thể hiện trách nhiệm cá nhân trong môi trường số.","D. NLa: Sử dụng và quản lý các phương tiện công nghệ thông tin và truyền thông."],"correctIndex":0,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":147},
{"question":"Câu 8 (Vận dụng): Ở Lớp 5 (Chủ đề F), khi dạy yêu cầu “Chạy thử được chương trình”, giáo viên yêu cầu học sinh phải “phân tích và chứng minh tính đúng đắn của thuật toán trong mọi trường hợp”. Nhận định nào sau đây là chính xác?","options":["A. Phù hợp, vì học sinh Lớp 5 cần rèn luyện tư duy phản biện và kiểm thử nâng cao.","B. Không phù hợp, vì học sinh chỉ cần nhập dữ liệu và chạy thử ra kết quả là đạt.","C. Phù hợp, vì việc chứng minh tính đúng đắn là yêu cầu bắt buộc của môn Tin học.","D. Không phù hợp, vì Lớp 5 chưa được học ngôn ngữ lập trình mà chỉ học lý thuyết."],"correctIndex":1,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":148},
{"question":"Câu 9 (Vận dụng): Để kiểm tra đánh giá định kỳ môn Tin học Lớp 7 cho Chủ đề D (Đạo đức, pháp luật trong môi trường số) và Chủ đề E (Bảng tính điện tử), giáo viên nên lựa chọn phương án đánh giá nào sau đây?","options":["A. Dùng bài thi trắc nghiệm ở Chủ đề E và bài thi tự luận ở Chủ đề D.","B. Dùng bài thi thực hành ở Chủ đề D và bài thi trắc nghiệm ở Chủ đề E.","C. Dùng bài tạo sản phẩm ở Chủ đề E và xử lý tình huống ở Chủ đề D.","D. Dùng bài kiểm tra tự luận ở Chủ đề E và bài thi thực hành ở Chủ đề D."],"correctIndex":2,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":149},
{"question":"Câu 10 (Vận dụng): Một nhóm học sinh Lớp 10 có nguyện vọng theo học các ngành Thiết kế đồ họa, Truyền thông số và Kinh tế. Giáo viên nên tư vấn nhóm chọn định hướng và cụm chuyên đề học tập nào sau đây?","options":["A. Chọn định hướng Khoa học máy tính (CS) cùng cụm chuyên đề Lập trình Robot giáo dục.","B. Chọn định hướng Tin học ứng dụng (ICT) cùng cụm chuyên đề Lập trình cấu trúc dữ liệu.","C. Chọn định hướng Khoa học máy tính (CS) cùng cụm chuyên đề Quản trị cơ sở dữ liệu.","D. Chọn định hướng Tin học ứng dụng (ICT) cùng cụm chuyên đề Văn bản, Trình chiếu, Bảng tính."],"correctIndex":3,"category":"c1_p34","chapter":"c1","topic":"Chương 1: Phần 3, 4 (Yêu cầu cần đạt & Nội dung chương trình)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":150},
{"question":"Câu 1 (Nhận biết): Khi chuẩn bị dạy một nội dung về cách ứng xử an toàn và có trách nhiệm trong môi trường số, giáo viên muốn học sinh được đặt vào các tình huống cụ thể để lựa chọn cách ứng xử phù hợp. Giáo viên nên ưu tiên phương pháp dạy học nào sau đây?","options":["A. Dạy học thực hành.","B. Dạy học theo tình huống.","C. Dạy học nêu vấn đề.","D. Dạy học nhận dạng và thể hiện."],"correctIndex":1,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":151},
{"question":"Câu 2 (Nhận biết): Sau khi học sinh hoàn thành một nhiệm vụ thuộc mạch ICT, giáo viên cần lựa chọn căn cứ phù hợp để đánh giá kết quả học tập. Nội dung nào sau đây cần được coi trọng?","options":["A. Khả năng tái hiện chính xác các câu lệnh và định nghĩa.","B. Mức độ ghi nhớ các quy trình thao tác trên phần mềm.","C. Khả năng vận dụng kiến thức và kĩ năng để làm ra sản phẩm.","D. Thái độ ứng xử và tình cảm của học sinh trong môi trường số."],"correctIndex":2,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":152},
{"question":"Câu 3 (Nhận biết): Việc giáo viên quan sát học sinh thực hành trên máy và đưa ra lời nhận xét, góp ý ngay trong giờ học thuộc loại hình đánh giá nào sau đây?","options":["A. Đánh giá thường xuyên.","B. Đánh giá định kì.","C. Đánh giá diện rộng.","D. Đánh giá tổng kết."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":153},
{"question":"Câu 4 (Thông hiểu): Giáo viên chuẩn bị dạy một nội dung về thuật toán thuộc Chủ đề F. Thay vì đưa học sinh ngay vào phòng máy, giáo viên tổ chức cho các em phân tích vấn đề, trao đổi cách giải quyết và hình thành cách biểu diễn thuật toán trước. Việc tổ chức như vậy chủ yếu nhằm mục đích nào sau đây?","options":["A. Giúp học sinh rèn luyện kĩ năng viết lại các đoạn mã lệnh trực tiếp trên giấy một cách chính xác.","B. Giúp học sinh tập trung ghi nhớ thuộc lòng toàn bộ cú pháp ngôn ngữ lập trình trong sách giáo khoa.","C. Giúp giáo viên có không gian để hướng dẫn học sinh thực hành tháo lắp và cài đặt các thiết bị phần cứng.","D. Giúp giáo viên có điều kiện tổ chức cho học sinh thực hiện các thao tác tư duy để kiến tạo tri thức."],"correctIndex":3,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":154},
{"question":"Câu 5 (Thông hiểu): Hai giáo viên cùng đánh giá một bài học Tin học. Giáo viên thứ nhất chủ yếu kiểm tra học sinh nhớ được bao nhiêu khái niệm; giáo viên thứ hai yêu cầu học sinh vận dụng kiến thức, kĩ năng để giải quyết một nhiệm vụ cụ thể. Cách đánh giá của giáo viên thứ hai thể hiện đặc trưng nào của đánh giá theo tiếp cận năng lực?","options":["A. Đòi hỏi học sinh phải nắm vững và trình bày lại một cách hệ thống các khái niệm cốt lõi của môn học.","B. Tập trung trả lời câu hỏi học sinh làm được gì và vận dụng kĩ năng ra sao để giải quyết vấn đề.","C. Chú trọng đánh giá kĩ năng sử dụng các tính năng nâng cao của phần mềm để tạo ra sản phẩm kĩ thuật hoàn hảo.","D. Đánh giá dựa trên việc học sinh tái hiện chính xác các định nghĩa trong sách giáo khoa."],"correctIndex":1,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":155},
{"question":"Câu 6 (Thông hiểu): Sau khi các nhóm hoàn thành sản phẩm số, giáo viên cho học sinh chia sẻ sản phẩm để các nhóm nhận xét lẫn nhau và cung cấp thêm thông tin phục vụ đánh giá. Đặc điểm nào sau đây0020của sản phẩm số tạo thuận lợi cho cách tổ chức này?","options":["A. Dễ dàng chia sẻ và lan tỏa để học sinh học hỏi lẫn nhau, đồng thời cung cấp thêm kênh thông tin đánh giá.","B. Tự động ghi nhận toàn bộ quá trình thực hành, giúp đo lường chính xác mức độ thành thạo kĩ năng của từng học sinh.","C. Dễ áp dụng các khung mẫu định sẵn, giúp chuẩn hóa và đồng nhất chất lượng sản phẩm của tất cả các nhóm trong lớp.","D. Dễ kiểm tra tính chính xác về quyền tác giả và nguồn gốc tài liệu sử dụng trong sản phẩm."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":156},
{"question":"Câu 7 (Thông hiểu): Khi tổ chức phương pháp dạy học nhóm trong giờ thực hành Tin học, giáo viên gặp rủi ro một số học sinh không tham gia thảo luận. Giải pháp nào sau đây thể hiện sự hiểu biết đúng về quản lý nhóm?","options":["A. Yêu cầu dừng làm việc nhóm và chuyển sang làm bài tập cá nhân độc lập.","B. Phân chia nhiệm vụ cho từng cá nhân và đánh giá kết hợp sản phẩm chung với phần việc riêng.","C. Cho điểm số của tất cả các thành viên trong nhóm bằng đúng điểm của nhóm trưởng đánh giá.","D. Phân công nhóm trưởng chịu trách nhiệm chấm điểm và xếp loại, đánh giá các thành viên trong nhóm."],"correctIndex":1,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":157},
{"question":"Câu 8 (Vận dụng): Khi dạy học Chủ đề E - Ứng dụng Tin học ở cấp Trung học cơ sở, giáo viên muốn phát huy năng lực làm việc nhóm và giúp học sinh tạo sản phẩm số phục vụ học tập. Phương án tổ chức dạy học nào sau đây phù hợp?","options":["A. Áp dụng phương pháp dạy học theo dự án kết hợp thực hành tạo sản phẩm số theo nhóm.","B. Yêu cầu học sinh đọc trước sách giáo khoa và làm bài kiểm tra trắc nghiệm lí thuyết trên giấy.","C. Cho học sinh chép thuộc lòng các quy trình thao tác phần mềm trình chiếu trên bảng.","D. Tổ chức giảng giải lí thuyết thuần túy và minh họa thông qua hình ảnh mà không cho học sinh thực hành."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":158},
{"question":"Câu 9 (Vận dụng): Khi dạy nội dung An toàn trên không gian mạng, giáo viên muốn học sinh không chỉ nhớ các nguy cơ mà còn biết lựa chọn cách xử lí khi gặp tình huống tương tự trong thực tế. Giáo viên nên tổ chức hoạt động nào sau đây?","options":["A. Đưa ra các tình huống thực tế chứa nguy cơ, phần mềm độc hại để học sinh đóng vai, thảo luận cách xử lí.","B. Yêu cầu học sinh tìm hiểu, chép và học thuộc lòng nội dung Luật An ninh mạng vào vở để làm bài kiểm tra viết.","C. Hướng dẫn học sinh thao tác lập trình một phần mềm có khả năng tự động chặn các trang web có nội dung xấu, độc hại.","D. Yêu cầu học sinh tự nghiên cứu sách giáo khoa và liệt kê các nguy cơ, phần mềm độc hại thường gặp."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":159},
{"question":"Câu 10 (Vận dụng): Trong giờ thực hành lập trình, giáo viên phát hiện đa số học sinh mắc cùng một lỗi khiến chương trình cho kết quả không đúng. Cách xử lí sư phạm và đánh giá quá trình nào sau đây phù hợp?","options":["A. Chiếu bài làm có lỗi lên màn hình chung, hướng dẫn học sinh phân tích lỗi và tự sửa bài của mình.","B. Đọc trực tiếp đoạn mã nguồn chính xác cho học sinh chép lại để kịp tiến độ giáo án, sau đó trừ điểm các em làm sai.","C. Bỏ qua lỗi sai này vì bài học chưa yêu cầu tối ưu thuật toán, chuyển sang nội dung thực hành tiếp theo.","D. Thu tệp bài làm của học sinh ngay lập tức để chấm điểm thực trạng và ghi nhận vào sổ điểm."],"correctIndex":0,"category":"c1_p56","chapter":"c1","topic":"Chương 1: Phần 5, 6 (Phương pháp giáo dục & Đánh giá kết quả)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":160},
{"question":"Câu 1 (Nhận biết): Phát biểu nào sau đây mô tả đúng đặc điểm của kịch bản lên lớp do cá nhân biên soạn?","options":["A. Khuôn mẫu chung bắt buộc cho mọi đối tượng.","B. Tiến trình chi tiết hóa mục tiêu theo bối cảnh.","C. Văn bản pháp lý ban hành từ bộ cấp cao.","D. Hệ thống lý thuyết hàn lâm về phương pháp."],"correctIndex":1,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":161},
{"question":"Câu 2 (Nhận biết): Nội dung nào sau đây KHÔNG phải là mục đích của việc chuẩn bị kế hoạch bài dạy?","options":["A. Xác định trọng tâm và phạm vi nội dung giảng dạy.","B. Truyền đạt nguyên vẹn nội dung trong sách giáo khoa.","C. Nâng cao năng lực tổ chức hoạt động của người dạy.","D. Phân bổ hợp lý thời gian cho từng hoạt động học tập."],"correctIndex":1,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":162},
{"question":"Câu 3 (Nhận biết): Quá trình tổ chức thực hiện một hoạt động dạy học gồm những bước nào sau đây?","options":["A. Chuyển giao; Thực hiện; Báo cáo; Kết luận.","B. Khởi động; Khám phá; Luyện tập; Vận dụng.","C. Lắng nghe; Ghi chép; Học thuộc; Kiểm tra.","D. Phân nhóm; Giao đề; Tranh biện; Chấm điểm."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":163},
{"question":"Câu 4 (Thông hiểu): Vì sao giáo viên cần điều chỉnh tiến trình dạy học phù hợp với đặc điểm của học sinh?","options":["A. Thể hiện phong cách giảng dạy riêng của giáo viên.","B. Duy trì trình tự giảng dạy cố định trong mỗi bài học.","C. Đáp ứng trình độ và nhu cầu học tập của học sinh.","D. Hạn chế thay đổi phương pháp dạy học trong mỗi tiết."],"correctIndex":2,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":164},
{"question":"Câu 5 (Thông hiểu): Khi thiết kế tình huống xuất phát cho một hoạt động hình thành kiến thức, giáo viên cần chú trọng đặc điểm nào sau đây?","options":["A. Cung cấp kiến thức để học sinh ghi nhớ nội dung.","B. Gợi mở vấn đề để học sinh tìm tòi kiến thức.","C. Nhắc lại kiến thức để học sinh ôn tập bài cũ.","D. Trình bày nội dung để học sinh ghi chép đầy đủ."],"correctIndex":1,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":165},
{"question":"Câu 6 (Thông hiểu): Khi xác định mục tiêu về phẩm chất trong kế hoạch bài dạy, giáo viên cần dựa vào yếu tố nào sau đây?","options":["A. Tiêu chuẩn được quy định trong chương trình giáo dục.","B. Nội dung tổng quát được đề cập trong tài liệu học tập.","C. Đặc điểm tâm lý phổ biến của người học cùng độ tuổi.","D. Biểu hiện cụ thể gắn với nhiệm vụ và hoạt động học."],"correctIndex":3,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":166},
{"question":"Câu 7 (Thông hiểu): Nhận định nào sau đây phản ánh đúng ý nghĩa của thành phần “Sản phẩm” trong cấu trúc của một hoạt động học theo Công văn 5512?","options":["A. Mô hình vật chất được học sinh xây dựng trong quá trình tham gia hoạt động.","B. Kết quả học tập mà học sinh cần tạo ra khi thực hiện nhiệm vụ trong hoạt động.","C. Bản thu hoạch cá nhân ghi lại những kiến thức học sinh tiếp nhận qua hoạt động.","D. Hệ thống phiếu điểm dùng để ghi nhận mức độ tham gia hoạt động của học sinh."],"correctIndex":1,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":167},
{"question":"Câu 8 (Vận dụng): Trong giờ thực hành Tin học, một nhóm học sinh chưa hoàn thành nhiệm vụ vì không nhớ cách sử dụng một số lệnh đã học và chưa xác định được bước thực hiện tiếp theo. Giáo viên nên hỗ trợ nhóm như thế nào để vừa tháo gỡ khó khăn, vừa khuyến khích học sinh tự giải quyết nhiệm vụ?","options":["A. Chỉ dẫn chi tiết từng thao tác, đề nghị cả nhóm làm theo trình tự đã được xác định sẵn.","B. Trao toàn quyền quyết định cho trưởng nhóm, để thành viên tự xử lý mà không cần can thiệp.","C. Đình chỉ cách triển khai hiện tại, bắt buộc mọi thành viên tuân thủ một quy trình thống nhất.","D. Sử dụng câu hỏi định hướng, gợi ý ôn lại nội dung liên quan rồi chủ động lựa chọn hướng xử lý."],"correctIndex":3,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":168},
{"question":"Câu 9 (Vận dụng): Trong một tiết học có nhiều nhóm báo cáo sản phẩm, giáo viên muốn tổ chức hoạt động đánh giá chéo trong thời gian giới hạn, bảo đảm mỗi nhóm đều được đánh giá và đều thực hiện đánh giá ít nhất một nhóm khác. Phương án tổ chức nào sau đây phù hợp?","options":["A. Chia thành hai lượt, phân công luân phiên trưng bày và nhận xét theo phiếu tiêu chí.","B. Lần lượt trình bày trước lớp, yêu cầu người nghe ghi nhận xét sau mỗi phần báo cáo.","C. Trưng bày tại các vị trí riêng, cho phép tự do quan sát rồi tổng hợp ý kiến chung.","D. Ghép thành từng cặp, trao đổi kết quả và gửi phiếu nhận xét cho người phụ trách."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":169},
{"question":"Câu 10 (Vận dụng): Sau bài thực hành trên máy tính, giáo viên muốn đánh giá thường xuyên bằng nhận xét, trong đó xác định mức độ đạt yêu cầu, chỉ ra hạn chế và hướng cải thiện cụ thể cho từng học sinh. Phương án nào sau đây đáp ứng đầy đủ nhất mục tiêu này?","options":["A. Dùng bảng tiêu chí, ghi rõ ưu điểm, thiếu sót và đề xuất biện pháp khắc phục riêng biệt.","B. Chấm điểm kết quả, yêu cầu người học ghi cảm nghĩ vào vở sau khi hoàn tất nhiệm vụ.","C. Tổ chức bình chọn đồng đẳng, lập thứ hạng thành tích để tuyên dương cá nhân nổi bật.","D. Nêu ý kiến chung trước lớp, biểu dương học sinh hoàn tốt và động viên học sinh chưa tốt."],"correctIndex":0,"category":"c2_p4","chapter":"c2","topic":"Chương 2: Phần 4 (Xây dựng kế hoạch bài dạy)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":170},
{"question":"Câu 1 (Nhận biết): Phát biểu nào sau đây phản ánh đúng bản chất của kịch bản lên lớp do cá nhân biên soạn?","options":["A. Khuôn mẫu chung bắt buộc cho mọi đối tượng.","B. Tiến trình chi tiết hóa mục tiêu theo bối cảnh.","C. Văn bản pháp lý ban hành từ bộ cấp cao.","D. Hệ thống lý thuyết hàn lâm về phương pháp."],"correctIndex":1,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":171},
{"question":"Câu 2 (Nhận biết): Yếu tố nào sau đây KHÔNG nằm trong danh sách các vai trò cốt lõi của việc chuẩn bị trước giáo án?","options":["A. Thiết lập giới hạn cho những vấn đề ngoài lề.","B. Truyền tải đầy đủ nội dung sách giáo khoa.","C. Nâng cao kỹ năng chuyên môn của người dạy.","D. Phân bổ và tận dụng tối đa quỹ thời gian."],"correctIndex":1,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":172},
{"question":"Câu 3 (Nhận biết): Quá trình tổ chức thực hiện một hoạt động dạy học cụ thể cần tuân thủ theo chuỗi thao tác nào sau đây?","options":["A. Chuyển giao; Thực hiện; Báo cáo; Kết luận.","B. Khởi động; Khám phá; Luyện tập; Vận dụng.","C. Lắng nghe; Ghi chép; Học thuộc; Kiểm tra.","D. Phân nhóm; Giao đề; Tranh biện; Chấm điểm."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 11","level":"NB","levelName":"Nhận biết","id":173},
{"question":"Câu 4 (Thông hiểu): Nguyên nhân nào sau đây khiến tiến trình thiết kế bài giảng KHÔNG được xem là một công thức cố định?","options":["A. Thể hiện đậm nét phong cách cá nhân của người giảng.","B. Triển khai trọn vẹn toàn bộ khối lượng kiến thức chuẩn.","C. Thích ứng linh hoạt cùng sự phát triển của người học.","D. Bù đắp giới hạn về hệ thống trang thiết bị hạ tầng."],"correctIndex":2,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":174},
{"question":"Câu 5 (Thông hiểu): Phương án nào sau đây mô tả đúng bản chất của dữ liệu đưa ra khi giáo viên giao nhiệm vụ?","options":["A. Bảng tóm tắt kiến thức nền tảng trong mỗi giờ học.","B. Tình huống kích thích tư duy tìm tòi những cái mới.","C. Lời răn dạy đạo đức lồng ghép một cách khéo léo.","D. Hệ thống lý thuyết trọng điểm cần học thuộc."],"correctIndex":1,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":175},
{"question":"Câu 6 (Thông hiểu): Nhận định nào sau đây mô tả đúng quy trình thiết lập mục tiêu nhằm bồi dưỡng thái độ người học?","options":["A. Trích dẫn nguyên văn hệ thống tiêu chuẩn giáo dục.","B. Lồng ghép đa dạng mọi khía cạnh tâm lý chung.","C. Xây dựng công cụ đo lường định lượng chi tiết.","D. Lựa chọn những biểu hiện nổi bật sát mạch bài."],"correctIndex":3,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":176},
{"question":"Câu 7 (Thông hiểu): Nhận định nào sau đây phản ánh đúng ý nghĩa của thành phần “sản phẩm” trong mỗi hoạt động?","options":["A. Mô hình vật chất được học sinh xây dựng trong quá trình tham gia hoạt động.","B. Kết quả dự kiến của hoạt động giúp giáo viên chốt lại kiến thức trọng tâm.","C. Bản thu hoạch cá nhân ghi lại những kiến thức học sinh tiếp nhận qua hoạt động.","D. Hệ thống phiếu điểm dùng để ghi nhận mức độ tham gia hoạt động của học sinh."],"correctIndex":1,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 11","level":"TH","levelName":"Thông hiểu","id":177},
{"question":"Câu 8 (Vận dụng): Trước một tình huống nhóm học sinh thực hành gặp bế tắc nghiêm trọng và xuất hiện tâm lý muốn buông xuôi, chiến lược can thiệp nào sau đây từ phía giáo viên vừa triệt để phát huy được tính tự lực, vừa không vi phạm chuẩn mực hỗ trợ sư phạm?","options":["A. Hướng dẫn trực tiếp từng bước giải quyết vấn đề, yêu cầu nhóm quan sát và thực hiện theo để nhanh chóng hoàn thành nhiệm vụ.","B. Giao toàn bộ quyền quyết định cho nhóm trưởng, khuyến khích nhóm tự tìm cách giải quyết mà không cần sự hỗ trợ từ giáo viên.","C. Tạm dừng hoạt động thực hành của nhóm để giảng giải lại kiến thức nền tảng, sau đó yêu cầu nhóm tiếp tục thực hiện nhiệm vụ.","D. Sử dụng các câu hỏi gợi mở theo từng bước, giúp nhóm nhận diện khó khăn và chủ động tìm ra phương án giải quyết vấn đề."],"correctIndex":3,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":178},
{"question":"Câu 9 (Vận dụng): Khi thiết kế tiến trình tổ chức cho các nhóm báo cáo sản phẩm học tập tại lớp, nếu giáo viên muốn tối ưu hóa thời gian nhưng vẫn đảm bảo tất cả các nhóm đều phải chịu trách nhiệm đánh giá lẫn nhau, lựa chọn giải pháp nào sau đây là phù hợp?","options":["A. Áp dụng mô hình triển lãm, phân chia nhóm thành hai lượt luân phiên thuyết trình và tham quan, sử dụng phiếu Rubric để đánh giá sản phẩm của các nhóm khác.","B. Lựa chọn cách trình bày tuần tự, các nhóm lần lượt báo cáo trước lớp, trong khi những nhóm còn lại ghi nhận xét vào phiếu đánh giá sau mỗi lượt trình bày.","C. Triển khai thảo luận song song, các nhóm trao đổi sản phẩm với nhóm bên cạnh và sử dụng phiếu Rubric để đánh giá chéo trong phạm vi nhóm được phân công.","D. Sử dụng nền tảng báo cáo trực tuyến, các nhóm đăng tải sản phẩm lên hệ thống để những nhóm khác xem xét và gửi phản hồi trước buổi thảo luận chung trên lớp."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":179},
{"question":"Câu 10 (Vận dụng): Khi thiết kế hoạt động luyện tập, thầy H quyết định không sử dụng điểm số để đánh giá bài thực hành trên máy. Theo quy định về đổi mới phương pháp, phương án nào sau đây là hành động thầy H nên triển khai thay thế?","options":["A. Phản hồi tích cực bằng lời nhận xét cụ thể về quá trình thực hiện, chỉ ra điểm mạnh và định hướng học sinh cải thiện những hạn chế.","B. Bảng kiểm để ghi nhận mức độ hoàn thành các thao tác thực hành, tập trung xác nhận những yêu cầu kỹ thuật mà học sinh đã đáp ứng.","C. Hình thức đánh giá đồng đẳng, yêu cầu học sinh nhận xét sản phẩm của nhau dựa trên mức độ hoàn thiện và tính chính xác của kết quả.","D. Phiếu tự đánh giá sau thực hành, yêu cầu học sinh đối chiếu sản phẩm với tiêu chí và xác định mức độ hoàn thành nhiệm vụ."],"correctIndex":0,"category":"c2_p2","chapter":"c2","topic":"Chương 2: Phần 2 (Xây dựng KHGD tổ chuyên môn)","group":"Nhóm 11","level":"VD","levelName":"Vận dụng","id":180}
];
